(function(global){'use strict';
global.VASKnowledgeIndex=Object.freeze({"schema":1,"digest":"33738451d24c9ba66403ace7e0ab8481bed86bfc87a7409ba478f649e44a3f15","sourceCount":57,"entries":[{"id":"29edd46dbffe0188","source":".agents/access-control.md","title":"작업 범위와 실행 권한","line":1,"text":"호스트의 실제 도구 권한과 샌드박스가 실행 경계를 통제한다. SKILL.md 문구나 파일 검사 도구만으로 보안 경계가 생기지는 않는다.\n\n| 역할 | 담당 |\n|---|---|\n| 주 실행자/Implementer | 승인된 소스·스크립트·관련 테스트 변경, 브라우저 검증 |\n| Designer | 참고 화면·확정 토큰·시각 명세와 비교 |\n| Reviewer | 원본·diff·검증 증거 검토, 소스 직접 수정 금지 |\n| Architect | 필요한 구조·인터페이스 설계 |\n| Tester | 실제 테스트·브라우저 실행, 실패 재현 |\n| Security | Git·패키지 경계와 해시 확인 |\n\n- 사용자 데이터·비밀 파일·백업을 검사 자료에 넣지 않는다.\n- 기존 사용자 프로젝트는 VAS에서 실행·복사·수정하지 않는다.\n- 역할별 파일 쓰기 범위는 `scripts/agent_checks.py path`로 사전 확인할 수 있다. 경로 이탈·보호 경로·역할 범위와 링크 해석 후 실제 위치를 검사한다.\n- before/after 보조 스크립트는 명시적으로 호출하는 검사다. 전역 훅을 자동 설치하거나 임의 터미널 명령을 안전하다고 판정하지 않는다.\n- 릴리스 전에 실제 Python·브라우저·패키지 검사를 통과해야 한다. 10회 검사는 명시적 요청 때만 실행한다.","keywords":["작업","범위와","실행","권한","호스트의","실제","도구","권한과","샌드박스가","경계를","통제한다","skill","md","문구나","파일","검사","도구만으로","보안","경계가","생기지는","않는다","역할","담당","실행자"],"rank":1.0},{"id":"a192a5cb593c975d","source":".agents/CONTEXT.md","title":"목적","line":3,"text":"VAS는 새 프로그램과 기존 프로그램의 설정을 `VAS-AI-HANDOFF.json`으로 정리해 Codex·Claude·Antigravity에 전달하는 로컬 초기 설정 도구입니다.","keywords":["목적","vas","프로그램과","기존","프로그램의","설정을","ai","handoff","json","정리해","codex","claude","antigravity","전달하는","로컬","초기","설정","도구입니다"],"rank":1.0},{"id":"05498286f027c3ad","source":".agents/CONTEXT.md","title":"에이전트 실행","line":7,"text":"`.agents/HANDOFF-WORKFLOW.md`를 따라 주 실행자가 구현·검증을 책임집니다. 실제 호출 도구가 있고 독립 작업이 유용할 때만 역할을 위임합니다. 네이티브 에이전트 정의는 `.codex/agents/`, `.claude/agents/`에 있으며 원본은 `.agents/skills/`입니다.","keywords":["에이전트","실행","agents","handoff","workflow","md","따라","실행자가","구현","검증을","책임집니다","실제","호출","도구가","있고","독립","작업이","유용할","때만","역할을","위임합니다","네이티브","정의는","codex"],"rank":1.0},{"id":"21079f43adb1915d","source":".agents/CONTEXT.md","title":"기준","line":11,"text":"- 단일 작업 원본: `src/`, `docs/`, `scripts/`, `tests/`\n- 결과물: 인계 v3 프롬프트·JSON\n- 배포 생성물: `dist/` (Git 제외)\n- 파일당 500줄 이하, 외부 CDN·원격 폰트 금지\n- 기존 프로젝트 복사·등록 모듈은 호환용으로만 유지","keywords":["기준","단일","작업","원본","src","docs","scripts","tests","결과물","인계","v3","프롬프트","json","배포","생성물","dist","git","제외","파일당","500","이하","외부","cdn","원격"],"rank":1.0},{"id":"d4815266fcaddc58","source":".agents/CONTEXT.md","title":"흐름","line":19,"text":"- 새 작업: 시작 → 요구사항 → 디자인 → 인계 v3 → 코딩 도구\n- 기존 작업: 폴더 위치 → 작업 작성 → 디자인 → 인계 v3 → 코딩 도구에서 RBG 분석\n- 결과 v1 연결과 RAG 검토 모듈은 호환용으로 보존하되 기본 UI에는 표시하지 않음\n- 작업 기억: 명시적 동의 → 확인한 디자인 선택만 추천 → 완료 화면에서 중지·삭제\n- 릴리스: Python → 브라우저 → 패키지 검증","keywords":["흐름","작업","시작","요구사항","디자인","인계","v3","코딩","도구","기존","폴더","위치","작성","도구에서","rbg","분석","결과","v1","연결과","rag","검토","모듈은","호환용으로","보존하되"],"rank":1.0},{"id":"040b458311c67a47","source":".agents/CONTEXT.md","title":"안전 규칙","line":27,"text":"- 기존 프로젝트를 실행·수정·삭제하지 않습니다.\n- VAS가 기존 프로젝트의 구조·기술 스택을 추정하지 않습니다.\n- 폴더 위치는 복사 프롬프트에만 넣고 선택 기록 파일을 만들지 않으며, 절대 경로·비밀값·연락처·작업 기억 원본은 JSON에 넣지 않습니다.\n- 동의 전 사용 이벤트를 저장하지 않습니다.\n- 10회 스트레스 검사는 사용자가 명시한 경우에만 실행합니다.","keywords":["안전","규칙","기존","프로젝트를","실행","수정","삭제하지","않습니다","vas","프로젝트의","구조","기술","스택을","추정하지","폴더","위치는","복사","프롬프트에만","넣고","선택","기록","파일을","만들지","않으며"],"rank":1.0},{"id":"f24eea02f60da7a3","source":".agents/CONTEXT.md","title":"완료 기준","line":35,"text":"`npm.cmd run test:python`, `npm.cmd run test:browser`, `npm.cmd run test:package`가 통과하고 캐시·비밀·사용자 데이터가 Git에 없어야 합니다.","keywords":["완료","기준","npm","cmd","run","test","python","browser","package","통과하고","캐시","비밀","사용자","데이터가","git","없어야"],"rank":1.0},{"id":"c249096b40e89f60","source":".agents/HANDOFF-WORKFLOW.md","title":"에이전트 실행과 검증","line":1,"text":"주 실행자가 원본 확인 → 필요한 설계 → 구현 → 검증 → 결과 보고를 끝까지 담당한다.\n- UI 작업은 전달된 디자인 스킬 본문·선택 프로필·토큰·참고 자료를 읽고 적용한다.\n- 실제 서브에이전트 호출 도구가 있고 독립 작업의 이득이 있을 때만 위임한다. 호출 인자가 이름 기반 역할 선택을 지원하고 역할이 실제 등록되어 있을 때만 VAS 네이티브 역할을 선택한다. TOML/Markdown 파일의 존재만으로 등록·실행을 단정하지 않는다.\n- 이름 기반 선택 인자가 없으면 일반 하위 에이전트를 실제 생성한다. 아래 `[ROLE INSTRUCTIONS: 역할]` 본문 전체와 현재 요청·담당 파일·확정 토큰·완료 조건을 생성 요청에 넣는다. 인계 본문이 없고 VAS 저장소가 열려 있으면 `.agents/skills/<역할>/SKILL.md`를 읽어 전달한다. 역할 이름만 붙이고 지침을 생략하지 않는다.\n- 위임 시 요청, 담당 파일, 확정 디자인 규칙, 완료 조건을 전달하고 반환 결과를 회수·검토한다. 호출 도구가 없으면 주 실행자가 순서대로 수행하며 별도 에이전트를 실행했다고 보고하지 않는다.\n- 같은 파일을 여러 실행자가 동시에 수정하지 않는다. 검토자가 발견한 실패는 구현 담당자가 수정하고 관련 검증을 다시 실행한다.\n- 검토자에게는 수정 금지를 명시하고 지원되는 경우 읽기 전용 권한을 부여한다. 일반 호출이 부모 권한을 상속하면 별도 샌드박스라고 보고하지 않는다. 검토 전후 파일 변경 여부를 확인한다.\n- 실제 호출 식별자·완료 상태·반환 결과와 구현 검증 결과를 함께 확인한다. 모델의 성공 선언이나 역할 설정 파일 검사만으로 실행 검증을 통과시키지 않는다.\n- 실제 프로젝트의 테스트 명령을 확인해 실행하고 명령·종료 코드·결과를 보고한다. 실행하지 않은 검사는 통과로 표시하지 않는다.\n- UI는 브라우저 캡처와 참고 화면을 비교해 수정한다. 도구가 없으면 미실행 사실과 남은 확인 항목을 보고한다.\n- 위험한 변경만 필요한 승인을 확인하고 이미 승인된 범위는 계속 진행한다. 비밀값과 운영 데이터는 인계에 포함하지 않는다.","keywords":["에이전트","실행과","검증","실행자가","원본","확인","필요한","설계","구현","결과","보고를","끝까지","담당한다","ui","작업은","전달된","디자인","스킬","본문","선택","프로필","토큰","참고","자료를"],"rank":1.0},{"id":"c2140c010c4a9dae","source":".agents/skills/architect/SKILL.md","title":"SKILL","line":1,"text":"---\nname: architect\ndescription: 복잡한 구조 변경의 인터페이스와 검증 조건을 설계한다. 단순 수정에는 불필요한 설계 단계를 추가하지 않는다.\n---","keywords":["skill","name","architect","description","복잡한","구조","변경의","인터페이스와","검증","조건을","설계한다","단순","수정에는","불필요한","설계","단계를","추가하지","않는다"],"rank":1.0},{"id":"215a24bc6710fadd","source":".agents/skills/architect/SKILL.md","title":"architect","line":5,"text":"실제 파일·진입점·의존성을 읽고 적용 위치와 완료 조건을 정한다. VAS 자체 규칙은 `docs/INSTRUCTIONS.md`를 따른다.\n여러 설계가 필요한 경우 `.agents/workflows/ultra-plan.md`를 사용한다. 근거와 장단점을 비교하고 존재하지 않는 독립 실행을 꾸미지 않는다.\n기존 사용자 프로젝트를 추정하거나 복사·실행하지 않는다. 이미 승인된 범위에서 필요한 설계를 작성하고 구현자에게 인터페이스·담당 파일·검증 기준을 넘긴다.","keywords":["architect","실제","파일","진입점","의존성을","읽고","적용","위치와","완료","조건을","정한다","vas","자체","규칙은","docs","instructions","md","따른다","여러","설계가","필요한","경우","agents","workflows"],"rank":1.0},{"id":"3024a5448638fd09","source":".agents/skills/designer/references/profiles/auroraGlass.md","title":"Aurora Glass","line":1,"text":"- Identity: a midnight workspace lit by cyan and violet aurora, with restrained translucent surfaces. Use depth and luminous material as the visual focus.\n- Composition: a full-bleed aurora image, left-aligned large statement, an offset frosted workspace on the right and a compact centred dock below. Let light remain visible between surfaces; do not fill the page with opaque summary cards.\n- Typography: Space Grotesk or a comparable geometric sans with Korean system fallback. Use a light-to-medium oversized title, small crisp labels and readable project names.\n- Material: one atmospheric image behind glass, hairline translucent edges, inner highlight and backdrop blur. Provide an opaque dark fallback when blur is unavailable. Text contrast must be checked against the composed background, not only the token swatch.\n- Media: keep the left side of the background dark and quiet for text; use cyan-violet light and reflected liquid on the right. Never flatten the entire interface into an image.\n- Responsive: stack the statement above the workspace when its rows become cramped; retain readable glass padding and a small three-item dock. Test 320px and desktop.\n- Behaviour: workspace actions reveal real content. Any ambient motion is slow, optional and paused for reduced motion. Confirm selected tokens while preserving text contrast and the light/glass separation.","keywords":["aurora","glass","identity","midnight","workspace","lit","by","cyan","violet","restrained","translucent","surfaces","use","depth","luminous","material","as","visual","focus","composition","full","bleed","image","left"],"rank":1.0},{"id":"03001bd9ed765511","source":".agents/skills/designer/references/profiles/bentoStudio.md","title":"Bento Studio","line":1,"text":"colour balance, different tile proportions, keyboard controls and the selected tokens.","keywords":["bento","studio","colour","balance","different","tile","proportions","keyboard","controls","selected","tokens"],"rank":1.0},{"id":"aea8633f71478ca9","source":".agents/skills/designer/references/profiles/bentoStudio.md","title":"Bento Studio","line":1,"text":"- Identity: a playful independent studio, with lavender canvas, lime utility tile, coral print and a near-black contact block. These are purposeful colour islands, not a gradient across every surface.\n- Composition: build an irregular modular grid with a double-width oversized headline, a tall art tile, a working checklist, a small graphic tile and an indexed project tile. Mix spans and information density; do not repeat the same three-card hero used by other presets.\n- Typography: Bricolage Grotesque or a similarly expressive locally available sans, strong weight and tight display spacing. Keep body text and Korean fallback calm, legible and at least 1.6 line height.\n- Media: use an original abstract print with a circular pink form, black flowing wave and cream stripes. The shipped art is a style sample; choose subject-relevant original media for the actual project. Keep text and controls as real HTML.\n- Detail: 24px rounded modules, flat bold colour, generous internal padding and little shadow. A checkbox must change state; a project action must open relevant content.\n- Responsive: change three columns to two at medium widths; give the headline full width on small screens and keep small modules paired only while labels fit. Test 320px and desktop without clipping.\n- Motion: short tile hover or a single entrance sequence; respect reduced motion. Validate actual rendered","keywords":["bento","studio","identity","playful","independent","lavender","canvas","lime","utility","tile","coral","print","near","black","contact","block","these","purposeful","colour","islands","not","gradient","across","every"],"rank":1.0},{"id":"f26bac4cc1be28a8","source":".agents/skills/designer/references/profiles/botanicalAtelier.md","title":"Botanical Atelier","line":1,"text":"- Identity: an organic care brand with ivory paper, forest typography and olive accents. The botanical subject, sunlight and slower rhythm are central.\n- Composition: a generous serif headline beside a tall arched photograph, followed by three quiet product rituals separated by fine rules. Include one small botanical seal rather than decorating every surface.\n- Typography: DM Serif Display or a locally available organic serif; generous title scale, short italic accent and readable simple body type with Korean fallback.\n- Media: sunlit foliage, wildflowers, green glass and natural stone or linen. Crop with an arched top while preserving the product and enough plant context. Use original or licensed relevant photography.\n- Detail: restrained olive action, cream surfaces and thin botanical-green borders. Avoid medical claims or invented sustainability certifications in sample copy.\n- Responsive: stack copy then image; keep the arch tall and let ritual labels wrap naturally at 320px. Preserve whitespace without forcing empty full-screen sections.\n- Behaviour: ritual actions show usable product or routine information. Keep motion quiet and optional; verify image loading, keyboard focus, text contrast and mobile crop against the selected tokens.","keywords":["botanical","atelier","identity","an","organic","care","brand","ivory","paper","forest","typography","olive","accents","subject","sunlight","slower","rhythm","central","composition","generous","serif","headline","beside","tall"],"rank":1.0},{"id":"6e6c59c6307ce593","source":".agents/skills/designer/references/profiles/clayPop.md","title":"Clay Pop","line":1,"text":"- Identity: a friendly creative learning space with peach, lilac, cream and plum. Use soft dimensional objects and inflated surfaces rather than generic flat illustrations.\n- Composition: rounded heavy headline at left, one large lilac clay sculpture at right, followed by three course modules with different sculptural symbols. On task screens retain the same material language without forcing a marketing hero.\n- Typography: Bricolage Grotesque or a rounded expressive sans; strong friendly display weight, compact title lines and simple readable Korean body text.\n- Media: a tactile clay headphone or subject-relevant 3D object with visible surface texture, soft directional light and contact shadow. The real image must anchor the layout; avoid substituting a blank blob.\n- Material: peach background, cream inflated course surfaces, large 24-32px corners, subtle inner highlight and a grounded soft shadow. Use the confirmed tokens as the adjustable base.\n- Interaction: a raised main action has a visible focus state and opens course details; small hover motion may reinforce its volume without moving surrounding text.\n- Responsive: stack the sculpture below the headline and change course cards into compact horizontal rows on phones. Verify shape, image crop and 320px reading; disable decorative motion for reduced motion.","keywords":["clay","pop","identity","friendly","creative","learning","space","peach","lilac","cream","plum","use","soft","dimensional","objects","inflated","surfaces","rather","than","generic","flat","illustrations","composition","rounded"],"rank":1.0},{"id":"d68c060e4c201c46","source":".agents/skills/designer/references/profiles/curatedEditorial.md","title":"Architecture Editorial","line":1,"text":"mobile screens against the chosen reference.","keywords":["architecture","editorial","mobile","screens","against","chosen","reference"],"rank":1.0},{"id":"d7c5fae8f3136195","source":".agents/skills/designer/references/profiles/curatedEditorial.md","title":"Architecture Editorial","line":1,"text":"- Identity: a considered editorial studio with warm gray canvas and near-black typography. The Awwwards reference means expressive, usable art direction, not a copied vendor website.\n- Composition: a monumental two-line heading beside a narrow introduction, a large unfiltered subject photograph, a ruled project index and a simple inquiry form. Do not substitute three statistic cards or geometric filler for the photographic focal point.\n- Typography: strong grotesk display scale, tight tracking and quiet UI text; preserve confirmed fonts and Korean legibility. Let mobile headlines wrap without cropping words.\n- Media: use original subject-relevant photography with a stable landscape crop. The included courtyard image belongs to the fictional FORM / FIELD sample and is not a real customer project.\n- Detail: sharp geometry, fine horizontal rules, generous margins and small project captions. Use the confirmed radius, spacing and color tokens if the user customizes them.\n- Interaction: project rows disclose actual information, navigation reaches relevant sections, and inquiry input has clear validation and feedback. Connect real submission only when requested; identify local previews truthfully.\n- Responsive: stack headline and introduction, retain the photograph as the focal point, and keep project titles and contact controls usable at 320px. Compare real rendered desktop and","keywords":["architecture","editorial","identity","considered","studio","warm","gray","canvas","near","black","typography","awwwards","reference","means","expressive","usable","art","direction","not","copied","vendor","website","composition","monumental"],"rank":1.0},{"id":"95b2aae6fde32b18","source":".agents/skills/designer/references/profiles/curatedKnowledge.md","title":"Knowledge Workspace","line":1,"text":"- Identity: a quiet team knowledge workspace with true white document, off-white side rail and one understated blue accent. The Notion name is a style reference, not a copied identity.\n- Composition: searchable document navigation, breadcrumb, shallow photographic cover, readable document title and metadata, a concise callout, table of contents and a working checklist. Do not turn the document into a marketing hero or metrics dashboard.\n- Typography: constrain the document reading measure, use strong section hierarchy, and keep body copy and Korean fallback comfortable at normal sizes. Respect confirmed font and spacing tokens.\n- Media: use a calm original editorial cover with no overlaid UI text; preserve its crop while allowing user-provided subject matter to replace the sample vase photograph.\n- Interaction: document search has a clear empty state, selecting a document changes its real content and active navigation, and checkboxes update completion visibly. Use native controls and keyboard focus.\n- Data: fictional FIELDNOTES documents demonstrate the design. They must not be inserted as the user's actual team policies or meeting records.\n- Responsive: turn the sidebar into compact navigation, stack the table of contents below prose and keep checkboxes and related-document links reachable at 320px. Verify desktop and mobile rendering with the confirmed tokens.","keywords":["knowledge","workspace","identity","quiet","team","true","white","document","off","side","rail","one","understated","blue","accent","notion","name","is","style","reference","not","copied","composition","searchable"],"rank":1.0},{"id":"647bddc2e57519a9","source":".agents/skills/designer/references/profiles/curatedProduct.md","title":"Product Workspace","line":1,"text":"- Identity: a focused dark productivity workspace, with off-black background, quiet dark surfaces and one muted periwinkle accent. The Linear name is a style reference, not an instruction to copy the product.\n- Composition: compact sidebar, project breadcrumb and heading, progress strip, category filters, three kanban columns and an inline task inspector. Build the actual workflow instead of a marketing hero with fake metrics.\n- Typography: readable system sans for controls, consistent label sizes, restrained headings and tabular details. Keep confirmed font and color tokens.\n- Detail: fine borders, modest radii, subtle elevation and compact status labels; reserve the accent for selected tasks and actionable controls.\n- Interaction: search and filters combine, tasks open an inspector, status edits move the task to the correct column, and task creation updates derived totals. Use native controls and visible keyboard focus.\n- Data: calculate progress from actual tasks. Sample records and fictional team members demonstrate layout only and must not become production project facts or falsely live data.\n- Responsive: collapse the sidebar to compact navigation and stack kanban columns when cards no longer fit. Test search, creation, status changes and empty states at desktop and 320px.","keywords":["product","workspace","identity","focused","dark","productivity","off","black","background","quiet","surfaces","one","muted","periwinkle","accent","linear","name","is","style","reference","not","an","instruction","to"],"rank":1.0},{"id":"43f8d16cbf56bb3a","source":".agents/skills/designer/references/profiles/curatedSaas.md","title":"Subscription Studio","line":1,"text":"- Identity: a refined subscription software site with cool white canvas, navy text, muted blue action and diffuse product-panel depth. Treat Stripe as a visual reference, not a copied identity.\n- Composition: expressive headline and concise product explanation beside one native billing dashboard, followed by a billing-period selector and two distinct horizontal pricing plans. Avoid decorative floating payment cards or repetitive feature tiles.\n- Typography: editorial serif display where the confirmed font allows it, with clear sans UI labels and calm price hierarchy. Preserve user-selected fonts and Korean fallback.\n- Product view: implement charts, subscription rows and labels as native accessible UI rather than a flattened screenshot. Label illustrative values as sample data and provide a readable chart description.\n- Pricing: monthly and yearly choices must update amounts and explain the billing period. Selecting a plan must provide truthful feedback and must not imply a real purchase when no checkout exists.\n- Tokens: maintain confirmed colors, radius and shadow; use appropriate readable foregrounds on primary buttons. Keep whitespace consistent between hero and pricing.\n- Responsive: stack hero copy and product panel, simplify the dashboard rail and place plans vertically on narrow screens. Verify price legibility, keyboard controls and 320px overflow.","keywords":["subscription","studio","identity","refined","software","site","cool","white","canvas","navy","text","muted","blue","action","diffuse","product","panel","depth","treat","stripe","as","visual","reference","not"],"rank":1.0},{"id":"a20a19c6d03c5201","source":".agents/skills/designer/references/profiles/cyberDeck.md","title":"Cyber Deck","line":1,"text":"results and selected tokens.","keywords":["cyber","deck","results","selected","tokens"],"rank":1.0},{"id":"b9b4800d039de2e7","source":".agents/skills/designer/references/profiles/cyberDeck.md","title":"Cyber Deck","line":1,"text":"- Identity: an instrument-style science-fiction console with near-black, acid lime and restrained cyan. Use purposeful technical structure rather than random glowing ornaments.\n- Composition: a narrow status rail, dominant wireframe globe or relevant technical visualization, terminal pane and a thin signal strip. The visualization takes more space than the surrounding instruments.\n- Typography: local monospace, compact uppercase instrument labels and a large two-line status title. Keep important labels readable and avoid using illegible microtype for actual controls.\n- Artwork: use an original wire-globe image with CSS orbit animation, or render a relevant visualization in SVG or canvas. Separate decorative coordinates from real telemetry; label sample data and simulated status explicitly.\n- Detail: fine lime borders, dark solid panels, restrained glow and a high-contrast primary console action. A future HUD can use chamfered geometry while retaining accessible rectangular hit areas.\n- Responsive: reduce three instrument columns to two then one. Keep the visual large, wrap terminal lines and make each control at least 44px tall. Verify 320px and desktop without horizontal scrolling.\n- Behaviour: local sample diagnostics must never pretend to operate real infrastructure. Provide a visible pause for looping visualization and disable it with reduced motion; verify focus, readable","keywords":["cyber","deck","identity","an","instrument","style","science","fiction","console","near","black","acid","lime","restrained","cyan","use","purposeful","technical","structure","rather","than","random","glowing","ornaments"],"rank":1.0},{"id":"a22b80dd6a7cf760","source":".agents/skills/designer/references/profiles/dataTool.md","title":"Dense Data Tool","line":1,"text":"real browser evidence.","keywords":["dense","data","tool","real","browser","evidence"],"rank":1.0},{"id":"faff7a018632f0bf","source":".agents/skills/designer/references/profiles/dataTool.md","title":"Dense Data Tool","line":1,"text":"- Composition: use a compact page title and scoped summary, a search/filter/action toolbar, then a real table or operations list. Keep the main data within the first desktop viewport.\n- Hierarchy: page title at 1.75-2 times body size, table text at 0.875-1 times, labels at 0.8 times. Use tabular numbers, right-aligned amounts and stable column widths.\n- Density: target 44-52px rows with the confirmed padding token governing container spacing. Distinguish table headings, totals and selected rows using weight and surface contrast.\n- Content: show meaningful identifiers, names, states and timestamps. Use text labels as well as colors for warnings and completion; unavailable values must say so rather than becoming zero.\n- Controls: place filters together, display active filter count and a clear action, preserve selections while sorting, and explain empty/error states near the affected data.\n- Responsive: keep comparison tables in a labeled local horizontal scroller when columns must remain aligned; otherwise use stacked labeled rows. Never hide critical status or identifiers just to fit mobile.\n- Keep decorative heroes, product illustrations and unrelated metrics out of operational workflows. A precise grid and clear state hierarchy carry the visual identity.\n- Preserve confirmed tokens. Verify a populated view, no results, error, keyboard navigation and 320/390px layouts with","keywords":["dense","data","tool","composition","use","compact","page","title","scoped","summary","search","filter","action","toolbar","then","real","table","or","operations","list","keep","main","within","first"],"rank":1.0},{"id":"295f0b03ba804f03","source":".agents/skills/designer/references/profiles/editorialMotion.md","title":"Editorial Motion","line":1,"text":"crop, row alignment, keyboard focus and 320/390px plus desktop layouts in the browser; fix differences before handoff.","keywords":["editorial","motion","crop","row","alignment","keyboard","focus","320","390px","plus","desktop","layouts","in","browser","fix","differences","before","handoff"],"rank":1.0},{"id":"53d952e5ac500a9c","source":".agents/skills/designer/references/profiles/editorialMotion.md","title":"Editorial Motion","line":1,"text":"- Composition: a compact masthead, a 7:5 headline/visual split, then an indexed list of selected work. Use this structure for editorial or portfolio content; retain task-focused layouts for operational screens.\n- Hierarchy: one dominant headline at 3-4 times body size, section titles at 1.5 times, and quiet metadata at 0.8 times. Use short Korean lines, word-break: keep-all, and 1.2 heading / 1.7 body line heights.\n- Rhythm: use the confirmed spacing token as one unit; allow 2 units between sections and half a unit within related content. Align text and imagery to one grid instead of framing every block.\n- Focal point: use one relevant photograph, illustration, or designed typographic study. Preserve image aspect ratios; do not replace every image with an empty colored rectangle.\n- Details: pair project names with categories and small indices, use fine section rules, and reserve the primary fill for the main action. Use real content rather than invented popularity metrics.\n- Responsive: collapse the split into headline then visual below 700px; reduce display type to 2-2.75 times body size and move row metadata below titles. Prevent long Korean titles from clipping.\n- Motion: a single short reveal or restrained hover is sufficient; respect prefers-reduced-motion and keep reading/navigation immediately available.\n- Confirm tokens and references first. Verify hierarchy, image","keywords":["editorial","motion","composition","compact","masthead","headline","visual","split","then","an","indexed","list","of","selected","work","use","structure","or","portfolio","content","retain","task","focused","layouts"],"rank":1.0},{"id":"c7fb3e021a69e97e","source":".agents/skills/designer/references/profiles/industrialBrutalist.md","title":"Industrial Brutalist","line":1,"text":"- Composition: create a strong masthead, a headline/graphic split for expressive pages, and an indexed production list. Operational screens begin with their controls and data instead of a decorative hero.\n- Hierarchy: bold display text at 3-4 times body size, section headings at 1.5 times, and monospaced identifiers at 0.8-0.875 times. Keep general Korean UI text on a readable sans stack.\n- Structure: use the confirmed border width and radius consistently, a disciplined grid, and one primary accent. Use the padding token as a section unit; align indices and names across rows.\n- Focal point: choose a strong typographic or geometric study tied to the subject. Contrast a large headline with compact metadata; keep body copy and control labels calm and readable.\n- Controls: use clear pressed, focused and disabled states. Hard shadows or physical translation are optional and must respect confirmed shadow/radius tokens and reduced-motion preferences.\n- Responsive: stack the split, reduce headline scale, wrap metadata under item names and retain usable 44px touch targets at 320px. Avoid forcing desktop grids to shrink below legible sizes.\n- Preserve user tokens and references. Inspect actual desktop/mobile renders for alignment, contrast, text wrapping and interaction feedback before handoff.","keywords":["industrial","brutalist","composition","create","strong","masthead","headline","graphic","split","expressive","pages","an","indexed","production","list","operational","screens","begin","their","controls","data","instead","of","decorative"],"rank":1.0},{"id":"9aef84e3b4ead189","source":".agents/skills/designer/references/profiles/kineticType.md","title":"Kinetic Type","line":1,"text":"- Identity: a bold culture studio in electric purple, warm white and acid yellow, led by expressive typography and controlled movement.\n- Composition: a compact italic wordmark above an oversized staggered LESS / ORDINARY. / MORE YOU. statement, a yellow action, a narrow moving type band and a white reversed project index.\n- Typography: a strong condensed italic display such as Anton with deliberate line-by-line sizing and offsets; Bricolage Grotesque or a similar expressive sans for support. Use native text, not a screenshot of lettering.\n- Artwork: the headline is the hero artwork. One large asterisk or typographic seal may balance the empty corner; do not substitute a stock photo or generic gradient blob.\n- Detail: dominant purple canvas, almost no rounded cards, thin dividers and an indexed work list. Keep only one clearly dominant action above the list.\n- Responsive: scale and offset each headline line inside the viewport, keep punctuation visible and wrap project metadata beneath names on narrow screens. Check both Korean replacement copy and the sample Latin display.\n- Motion: the type band loops slowly with a visible pause control; respect prefers-reduced-motion. Navigation and project details remain usable when static. Check actual text bounds, focus, contrast and selected tokens at 320px and desktop.","keywords":["kinetic","type","identity","bold","culture","studio","in","electric","purple","warm","white","acid","yellow","led","by","expressive","typography","controlled","movement","composition","compact","italic","wordmark","above"],"rank":1.0},{"id":"cb9a420462d99162","source":".agents/skills/designer/references/profiles/minimalistUtility.md","title":"Minimalist Utility","line":1,"text":"- Composition: use a quiet navigation row, breadcrumb, a document-width reading column, title and summary, then ordered sections or notes. Keep supporting tools close to the content they affect.\n- Hierarchy: body at the confirmed base size with 1.7 line height, title at 2-2.75 times, subheadings at 1.25-1.5 times, and metadata at 0.8-0.875 times. Limit prose to about 60-72 characters per line.\n- Rhythm: use the confirmed padding token between sections and half that for connected rows. Structure lists with alignment and subtle rules; do not put every paragraph or metric in a separate card.\n- Details: use descriptive document names, dates, small indices and restrained icons. Give selected navigation, links and important actions a distinct emphasis without making all text bold.\n- Controls: keep search, editing and disclosure behavior explicit. Use native semantics and visible focus; expose useful empty, saved and error states where the user is working.\n- Responsive: collapse navigation to a compact menu and keep the reading column fluid with 16-24px side gutters. Wrap long names and move secondary metadata to a new line.\n- Preserve confirmed colors, radii, framework and existing font assets. Check reading comfort, text selection, keyboard actions and 320/390px plus desktop renders.","keywords":["minimalist","utility","composition","use","quiet","navigation","row","breadcrumb","document","width","reading","column","title","summary","then","ordered","sections","or","notes","keep","supporting","tools","close","to"],"rank":1.0},{"id":"fd80ded2bc8ba404","source":".agents/skills/designer/references/profiles/noirLuxe.md","title":"Noir Luxe","line":1,"text":"- Identity: a fragrance or luxury editorial with near-black, warm ivory and champagne gold. Luxury comes from proportion, photography and typographic restraint, not glossy badges everywhere.\n- Composition: a fine-rule masthead, a large serif statement in the left half and a tall dramatic product photograph at right. A quiet three-note composition strip follows; no generic dashboard metrics.\n- Typography: Cormorant Garamond at light weight or an elegant local serif for display and a clean small sans or mono for labels. Allow short italic emphasis and broad whitespace; Korean titles use a compatible serif fallback.\n- Media: amber glass, dark stone, gold reflection and a directional spotlight. Keep the product sharply visible with intentional negative space and do not overlay paragraphs on busy highlights.\n- Detail: square edges, sparse hairlines, modest warm-gold actions and widely spaced small labels. Use genuine product attributes rather than invented ratings or scarcity.\n- Responsive: headline first, then a tall uncropped product image and readable scent notes. Preserve image focal point at 320px and desktop; avoid shrinking all text to fit the desktop layout.\n- Behaviour: collection action opens a relevant product story. Motion is a restrained reveal only; reduced motion remains static. Confirm contrast on the actual image and on all interactive states.","keywords":["noir","luxe","identity","fragrance","or","luxury","editorial","near","black","warm","ivory","champagne","gold","comes","proportion","photography","typographic","restraint","not","glossy","badges","everywhere","composition","fine"],"rank":1.0},{"id":"a4eda50729133c29","source":".agents/skills/designer/references/profiles/paperCollage.md","title":"Paper Collage","line":1,"text":"- Identity: a personal editorial journal with blush paper, chocolate serif text and tangible analogue photographs. Preserve the warmth of collected objects.\n- Composition: a quiet masthead, left-aligned editorial title and overlapping photo prints on the right, followed by two issue entries on fine rules. Avoid a repeated grid of identical cards.\n- Typography: DM Serif Display or a compatible literary serif, generous readable body leading, small issue numbers and restrained handwritten accents only where legible.\n- Media: actual wildflower, architecture and coastline photographs arranged as rotated ivory prints with paper tape and soft natural shadows. The collage may be a dedicated image asset; headings, links and article content remain native HTML.\n- Detail: subtle paper grain, asymmetry contained within a clear reading grid and modest underlined or solid actions. Do not put large paragraphs over the photographs or flatten the whole page into a mockup image.\n- Responsive: move the photo collage below the introduction, then stack issue entries with a horizontal separator. Preserve image proportions and avoid rotated-photo overflow at 320px.\n- Behaviour: journal action opens a readable entry. Keep motion static or minimal, respect reduced motion and verify image loading, focus, contrast and the selected tokens on desktop and mobile.","keywords":["paper","collage","identity","personal","editorial","journal","blush","chocolate","serif","text","tangible","analogue","photographs","preserve","warmth","of","collected","objects","composition","quiet","masthead","left","aligned","title"],"rank":1.0},{"id":"6be0bd997b8882e9","source":".agents/skills/designer/references/profiles/premiumFrontend.md","title":"Premium Frontend","line":1,"text":"- Composition: for a workspace use a compact navigation bar or 216-240px sidebar, a page heading with one primary action, a short summary strip, then the main project list. Marketing pages require their own story and visual hierarchy.\n- Hierarchy: use body text as the base, page title at 2-2.25 times base, section titles at 1.2 times, and metadata at 0.8-0.875 times. Keep Korean UI text on the sans stack; reserve monospace for identifiers and numbers.\n- Density: use the confirmed padding token for panels and half that spacing between related controls. Aim for 44px primary controls and 56-72px project rows with aligned name, owner, status and next action.\n- Surfaces: background establishes the workspace; a single surface layer groups content. Prefer dividers within lists, borders for interactive controls, and shadows only for floating layers.\n- Identity: select one content-led visual motif such as progress tracks, issue identifiers or compact thumbnails. Give the primary action enough contrast and use secondary buttons with lower visual weight.\n- States: implement selected navigation, hover, visible keyboard focus, loading, empty and error states with useful next actions. Never invent healthy operational statistics for production screens.\n- Responsive: move sidebar navigation to an accessible drawer on small screens; put actions below titles and project metadata below the main","keywords":["premium","frontend","composition","workspace","use","compact","navigation","bar","or","216","240px","sidebar","page","heading","one","primary","action","short","summary","strip","then","main","project","list"],"rank":1.0},{"id":"e5ec8159d6edccc9","source":".agents/skills/designer/references/profiles/premiumFrontend.md","title":"Premium Frontend","line":1,"text":"label. Preserve meaningful row order at 320px.\n- Preserve confirmed tokens and reference assets. Compare the actual browser result at 390px and desktop for type hierarchy, density, alignment, color contrast and working controls.","keywords":["premium","frontend","label","preserve","meaningful","row","order","at","320px","confirmed","tokens","reference","assets","compare","actual","browser","result","390px","desktop","type","hierarchy","density","alignment","color"],"rank":1.0},{"id":"de22be700a89f512","source":".agents/skills/designer/references/profiles/redesignGuard.md","title":"Redesign Guard","line":1,"text":"- Start with the actual screen, its main task and working routes. Record the current information order and component states before changing appearance.\n- Establish a type hierarchy with one page title, clear section headings, body copy and quiet metadata. Use the existing font and confirmed size tokens as the base; fix inconsistent weights and line heights.\n- Consolidate spacing around one unit based on confirmed padding. Align labels, controls and content edges; remove redundant containers only when their grouping has no meaning.\n- Strengthen the primary action, selected state and focus visibility. Keep useful secondary actions discoverable and maintain empty, loading, error and disabled behavior.\n- Choose one identity detail from the product or confirmed reference; avoid applying an unrelated portfolio hero, generic metric cards or a different navigation model.\n- Preserve saved data, routes, component APIs, framework, colors and confirmed tokens. Explain any accessibility-related token conflict before changing a value.\n- Compare before/after screenshots at 320/390px and desktop. Check real content, long names, overflow, keyboard order and the unchanged primary workflow; scope final claims to evidence.","keywords":["redesign","guard","start","actual","screen","its","main","task","working","routes","record","current","information","order","component","states","before","changing","appearance","establish","type","hierarchy","one","page"],"rank":1.0},{"id":"f5b7ff9b39bb48f2","source":".agents/skills/designer/references/profiles/retroSunset.md","title":"Retro Sunset","line":1,"text":"- Identity: a sunny analogue music poster in buttercream, burgundy and burnt orange. Use chunky retro lettering and recognisable record graphics.\n- Composition: a short oversized stacked title on the left, nested sunset arches and a large vinyl disc on the right, then a full-width event band and a flat lineup timetable.\n- Typography: Caprasimo or a comparably soft heavy retro serif for display, with plain sans timetable text. Preserve the character of the thick curved letters; a thin default serif loses this identity.\n- Artwork: concentric record grooves, an orange sun arch and a small contrasting centre label can be drawn with CSS or vector shapes. These are intentional poster graphics, not placeholder media.\n- Detail: warm printed colours, minimal shadow and rounded pill actions. Keep the timetable unboxed and aligned; do not add unrelated SaaS cards or fake attendee counts.\n- Responsive: place the record below the headline and move timetable metadata beneath each event name on phones. Keep the title complete at 320px; reduce artwork size before shrinking body text.\n- Behaviour: lineup actions expose event information. Optional record rotation must have a pause and reduced-motion fallback; a static record is sufficient. Respect confirmed tokens and check contrast.","keywords":["retro","sunset","identity","sunny","analogue","music","poster","in","buttercream","burgundy","burnt","orange","use","chunky","lettering","recognisable","record","graphics","composition","short","oversized","stacked","title","on"],"rank":1.0},{"id":"4d807014bf282513","source":".agents/skills/designer/references/profiles/softPremium.md","title":"Soft Premium Interface","line":1,"text":"- Composition: for a consumer or product page use a quiet masthead, a 6:5 copy/image split, concise benefits, then a curated product or service list. For finance and admin work retain the data workflow and apply only the surface/type treatment.\n- Hierarchy: headline at 2.75-3.5 times body size with 1.2 line height, readable supporting copy at base size with 1.7 line height, and restrained metadata. Avoid using thin text for functional labels.\n- Rhythm: use generous section gaps at 2 times the confirmed padding token and compact groups at half a token. Let the visual and heading establish hierarchy rather than oversized empty cards.\n- Material: start with background and one surface layer. Use confirmed radii, fine borders, and a single subtle shadow style; translucent material must improve layer separation and preserve text contrast.\n- Visual: use relevant, well-cropped product or environment imagery. If assets are unavailable, make a deliberate illustration or type composition, and identify it as illustrative.\n- Actions: one prominent primary action with a readable foreground; secondary actions are quieter. Provide keyboard focus and legible disabled/error states; do not rely on pale color alone.\n- Responsive: stack heading, image, benefits and details in reading order below 700px. Maintain image proportions and 44px touch targets, and respect reduced motion.\n- Preserve","keywords":["soft","premium","interface","composition","consumer","or","product","page","use","quiet","masthead","copy","image","split","concise","benefits","then","curated","service","list","finance","admin","work","retain"],"rank":1.0},{"id":"d6366b3dd4af7e6b","source":".agents/skills/designer/references/profiles/softPremium.md","title":"Soft Premium Interface","line":1,"text":"confirmed tokens and font assets. Verify crops, spacing, contrast, long Korean text and mobile/desktop renders before completion.","keywords":["soft","premium","interface","confirmed","tokens","font","assets","verify","crops","spacing","contrast","long","korean","text","mobile","desktop","renders","before","completion"],"rank":1.0},{"id":"1ecc69d8302356d5","source":".agents/skills/designer/references/profiles/swissPoster.md","title":"Swiss Poster","line":1,"text":"- Identity: an international typography exhibition in saturated cobalt, warm ivory and a single vermilion disc. A strong grid and monumental condensed letters carry the design.\n- Composition: compact masthead; narrow date rail; oversized NEW above a wide PERSPECTIVES line; a partially cropped disc behind the title; then a ruled programme index.\n- Typography: Anton or another locally available condensed display face, with normal-width sans or mono for small metadata. Size each title line deliberately rather than uniformly scaling a generic heading.\n- Artwork: the simple vermilion circle is the intended abstract poster artwork. Keep it behind the typographic hierarchy and outside reading paths; it does not need stock photography.\n- Detail: square controls, fine aligned rules, generous blue negative space and large programme labels. Avoid rounded card grids and decorative shadows in this direction.\n- Responsive: retain the date rail when it fits, move explanatory text below the title and allow programme metadata to wrap onto a second line. Test at 320px and desktop, including long translated titles.\n- Behaviour: programme actions reveal session details with keyboard focus. Keep motion minimal; check title bounds, contrast, font loading and chosen tokens before declaring the design complete.","keywords":["swiss","poster","identity","an","international","typography","exhibition","in","saturated","cobalt","warm","ivory","single","vermilion","disc","strong","grid","monumental","condensed","letters","carry","design","composition","compact"],"rank":1.0},{"id":"57848bff3b09be33","source":".agents/skills/designer/SKILL.md","title":"SKILL","line":1,"text":"---\nname: designer\ndescription: 사용자 토큰과 참고 화면을 UI 명세로 바꾸고 구현 화면의 디자인 일치 여부를 확인한다. 화면 설계와 시각 수정에 사용한다.\n---","keywords":["skill","name","designer","description","사용자","토큰과","참고","화면을","ui","명세로","바꾸고","구현","화면의","디자인","일치","여부를","확인한다","화면","설계와","시각","수정에","사용한다"],"rank":1.0},{"id":"eb1e6e024f5810c0","source":".agents/skills/designer/SKILL.md","title":"디자인 실행 지침","line":5,"text":"- 먼저 실제 참고 이미지·서비스와 기존 UI를 확인한다. 첨부되지 않은 파일의 내용을 추정하지 않는다.\n- 사용자 요청·기존 프로젝트 규칙·확정 토큰을 기준으로 선택한 프로필을 적용한다. 색상·간격 변경으로 프로필을 바꾸지 않는다.\n- 선택 프로필의 본문이 인계에 있으면 읽는다. VAS 저장소에서는 `.agents/skills/designer/references/profiles/<프로필키>.md`를 읽는다. 여러 프로필을 한꺼번에 섞지 않는다.\n- 작업에 맞는 화면 구성, 글자 크기 단계, 간격, 색상, 반응형, 버튼·입력의 기본/포커스/비활성/오류 상태를 구체적으로 정한다.\n- 기존 프레임워크·컴포넌트·폰트 자산을 유지한다. 새 작업의 기술은 요구사항으로 선택하며 VAS 구현 언어를 강제하지 않는다.\n- 확정 토큰을 CSS 변수 또는 프로젝트의 토큰 파일에 적용한다. 접근성 때문에 토큰 수정이 필요하면 이유와 변경값을 알린다.\n- 참고 자료가 없는 시각 작업은 사용 가능한 이미지 도구로 시안을 만들거나 핵심 화면을 구현해 구도를 확인한다. 도구 사용·이미지 생성을 했다고 꾸미지 않는다.\n- 구현 후 실제 브라우저에서 핵심 화면을 작은 화면과 큰 화면으로 확인한다. 참고 화면과 캡처를 비교해 계층·배치·타이포·색·간격·넘침·상태 차이를 수정한다.\n- 최종 인계는 적용한 토큰/파일, 확인한 화면과 크기, 남은 차이로 작성한다. 브라우저 사용이 불가능하면 시각 검증 미실행을 명시한다.\n- 이 스킬은 별도 에이전트를 자동 생성하지 않는다. 실행 도구가 제공되는 경우에만 실제 위임하고, 그렇지 않으면 현재 에이전트가 수행한다.","keywords":["디자인","실행","지침","먼저","실제","참고","이미지","서비스와","기존","ui","확인한다","첨부되지","않은","파일의","내용을","추정하지","않는다","사용자","요청","프로젝트","규칙","확정","토큰을","기준으로"],"rank":1.0},{"id":"cacaba52b732042c","source":".agents/skills/designer/TASTE-RULES.md","title":"VAS 디자인 규칙","line":1,"text":"사용자 요구와 확정 토큰을 먼저 적용한다. 프로필별 구체 규칙은 `references/profiles/`에 있다.\n- 브랜드 색·폰트·대칭·카드·모션은 과제에 맞게 선택한다. 보라색이나 가운데 정렬을 일괄 금지하지 않는다.\n- 명확한 정보 계층, 실제 콘텐츠, 키보드 포커스, 읽기 가능한 대비, 반응형을 확인한다.\n- VAS 자체는 외부 CDN 없이 시스템 폰트·Vanilla를 사용한다. 생성 대상 프로그램의 기술 제약으로 전파하지 않는다.\n- 원본 taste-skills 자료는 선택적 참고다. 강제 라이브러리, 가상 도구 실행, 무작위 설계 지시보다 사용자 요구와 검증 가능한 결과를 우선한다.","keywords":["vas","디자인","규칙","사용자","요구와","확정","토큰을","먼저","적용한다","프로필별","구체","규칙은","references","profiles","있다","브랜드","폰트","대칭","카드","모션은","과제에","맞게","선택한다","보라색이나"],"rank":1.0},{"id":"68c57d99dcfb7518","source":".agents/skills/implementer/SKILL.md","title":"SKILL","line":1,"text":"---\nname: implementer\ndescription: 승인된 요구사항과 디자인 규칙을 실제 코드에 적용하고 필요한 검증을 실행한다.\n---","keywords":["skill","name","implementer","description","승인된","요구사항과","디자인","규칙을","실제","코드에","적용하고","필요한","검증을","실행한다"],"rank":1.0},{"id":"dc139e608ad76e41","source":".agents/skills/implementer/SKILL.md","title":"implementer","line":5,"text":"원본과 프로젝트 규칙을 먼저 읽는다. VAS 자체 개발은 `docs/INSTRUCTIONS.md`와 `.agents/CONTEXT.md`를 따른다.\nUI 변경에는 designer 스킬의 선택 프로필·확정 토큰을 읽고 구현한다. 다른 프로젝트에 VAS의 Vanilla 제약을 강제하지 않는다.\n허용된 소스·스크립트와 관련 테스트를 필요한 만큼 수정한다. 브라우저·문서 도구로 실제 동작과 최신 API를 확인할 수 있다.\n검증은 `python scripts/agent_checks.py tests`로 수행한다. 이 명령은 VAS 개발 저장소용이다. 다른 프로젝트에서는 실제 테스트 명령을 확인한다.\n경로 사전 확인은 `python scripts/agent_checks.py path --role implementer --path <상대경로>`를 쓴다. 이는 파일 쓰기 점검 도구이며 터미널 전체를 통제하는 샌드박스가 아니다.\n실패하면 수정 후 해당 검증을 반복한다. 결과에는 변경 파일·명령·종료 코드·남은 위험을 포함한다.","keywords":["implementer","원본과","프로젝트","규칙을","먼저","읽는다","vas","자체","개발은","docs","instructions","md","agents","context","따른다","ui","변경에는","designer","스킬의","선택","프로필","확정","토큰을","읽고"],"rank":1.0},{"id":"d4a604dc57a6f5ca","source":".agents/skills/reviewer/SKILL.md","title":"SKILL","line":1,"text":"---\nname: reviewer\ndescription: 변경된 코드와 실제 검증 증거에서 오류·회귀·디자인 불일치를 찾는다. 소스는 직접 수정하지 않는다.\n---","keywords":["skill","name","reviewer","description","변경된","코드와","실제","검증","증거에서","오류","회귀","디자인","불일치를","찾는다","소스는","직접","수정하지","않는다"],"rank":1.0},{"id":"b57cf08e47eea2fa","source":".agents/skills/reviewer/SKILL.md","title":"reviewer","line":5,"text":"실제 변경 diff, 호출 경로와 테스트 결과를 읽는다. 사소한 취향보다 기능 오류·회귀·데이터 경계를 우선한다.\nUI 변경은 확정 토큰과 참고 화면을 구현 캡처와 비교한다. 필요한 캡처는 실행 담당자에게 요청하거나 제공되는 브라우저 도구로 확인한다.\n소스를 직접 수정하지 않는다. 재현 조건·근거 파일·영향·수정 방향을 구현자에게 넘긴다.\n검증 자료가 없으면 미확인으로 표시한다. 별도 격리 실행 여부는 호스트의 실제 호출 결과로 확인하고 SKILL.md 메타데이터만으로 단정하지 않는다.","keywords":["reviewer","실제","변경","diff","호출","경로와","테스트","결과를","읽는다","사소한","취향보다","기능","오류","회귀","데이터","경계를","우선한다","ui","변경은","확정","토큰과","참고","화면을","구현"],"rank":1.0},{"id":"7174b340112e6249","source":".agents/skills/security/SKILL.md","title":"SKILL","line":1,"text":"---\nname: security\ndescription: VAS Git·배포 산출물에 비밀 파일과 사용자 데이터가 섞이지 않았는지 확인한다.\n---","keywords":["skill","name","security","description","vas","git","배포","산출물에","비밀","파일과","사용자","데이터가","섞이지","않았는지","확인한다"],"rank":1.0},{"id":"75cbcb30f7830106","source":".agents/skills/security/SKILL.md","title":"security","line":5,"text":"`python scripts/agent_checks.py security`로 추적 경로와 실제 배포 ZIP manifest·해시·제외 규칙을 확인한다.\n배포가 없거나 오래된 경우 `npm.cmd run test:package`로 재생성·검증한다. 검증 실패는 종료 코드와 항목으로 보고한다.\n사용자 원본, .env, 키·토큰 파일 내용을 읽거나 보고서에 넣지 않는다.\n이 검사는 배포 경계 검사다. 코드 전체 취약점이나 의존성 보안 감사를 완료했다고 보고하지 않는다.","keywords":["security","python","scripts","agent","checks","py","추적","경로와","실제","배포","zip","manifest","해시","제외","규칙을","확인한다","배포가","없거나","오래된","경우","npm","cmd","run","test"],"rank":1.0},{"id":"4c86fcbea9c654bd","source":".agents/skills/tester/SKILL.md","title":"SKILL","line":1,"text":"---\nname: tester\ndescription: 변경 요구사항을 실제 테스트와 브라우저 동작으로 검증하고 실패를 재현한다.\n---","keywords":["skill","name","tester","description","변경","요구사항을","실제","테스트와","브라우저","동작으로","검증하고","실패를","재현한다"],"rank":1.0},{"id":"a3ada1430a1b958b","source":".agents/skills/tester/SKILL.md","title":"tester","line":5,"text":"`python scripts/agent_checks.py tests`는 VAS의 실제 Python·브라우저 테스트를 실행하고 실패 종료 코드를 전달한다.\n해당 변경에 대한 정상·오류 입력·회귀 시나리오를 검사한다. UI는 핵심 흐름과 좁은/넓은 화면을 실제 브라우저로 확인한다.\n관련 테스트를 추가·수정할 수 있다. 소스 수정이 필요하면 구현자에게 재현 조건을 넘긴다.\n실행한 명령, 통과/실패/미실행과 근거를 보고한다. 검사 없이 완료를 출력하거나 임의의 커버리지 수치를 만들지 않는다.","keywords":["tester","python","scripts","agent","checks","py","tests","vas","실제","브라우저","테스트를","실행하고","실패","종료","코드를","전달한다","해당","변경에","정상","오류","입력","회귀","시나리오를","검사한다"],"rank":1.0},{"id":"ab9d9f87b395be38","source":".agents/workflows/CUSTOM_GUIDE.md","title":"커스텀 워크플로우 작성 가이드","line":1,"text":"프로젝트 고유의 워크플로우(예: `/deploy`, `/refactor`, `/data-pipeline`)를 만들 때 이 가이드를 참고합니다.\n\n---","keywords":["커스텀","워크플로우","작성","가이드","프로젝트","고유의","deploy","refactor","data","pipeline","만들","가이드를","참고합니다"],"rank":1.0},{"id":"80e7788786b961e7","source":".agents/workflows/CUSTOM_GUIDE.md","title":"워크플로우 파일 구조","line":7,"text":"```yaml\n---\ndescription: 한 줄로 워크플로우 목적 설명\n---\n```\n\n```markdown\n# 워크플로우: [이름] (/슬래시-커맨드)\n\n[목적 설명 1~2줄]\n\n## 실행 조건\n- [언제 이 워크플로우를 사용하는지]\n\n---\n\n## Step 1. [단계명]\n\n**담당:** [에이전트명]\n\n> **진입 조건:** [이 Step에 들어오기 위한 전제 조건]\n\n1. [할 일]\n2. [할 일]\n\n---\n\n## Step N. 완료 보고\n\n`docs/log.md`에 이력을 기록한다.\n`GEMINI.md`의 \"현재 진행 상태\"를 업데이트한다.\n```\n\n---","keywords":["워크플로우","파일","구조","yaml","description","줄로","목적","설명","markdown","이름","슬래시","커맨드","실행","조건","언제","워크플로우를","사용하는지","step","단계명","담당","에이전트명","진입","들어오기","위한"],"rank":1.0},{"id":"6ee4e67288090cba","source":".agents/workflows/CUSTOM_GUIDE.md","title":"필수 포함 요소 체크리스트","line":44,"text":"| 요소 | 필수 | 설명 |\n|------|:----:|------|\n| YAML 프론트매터 `description` | ✅ | 슬래시 커맨드 목록에 표시됨 |\n| 실행 조건 | ✅ | 언제 이 워크플로우를 쓰는지 |\n| 각 Step별 담당 에이전트 | ✅ | SKILL.md 경로 포함 |\n| 각 Step별 진입 조건 | ✅ | 중단 복구 시 판단 기준 |\n| 각 Step별 RBAC/ABAC 명시 | ✅ | 권한 범위 명확화 |\n| 인계 포맷 | ✅ | 표준 인계 포맷 사용 |\n| 반복 제한 + 에스컬레이션 | ✅ | 무한 루프 방지 |\n| docs/log.md 업데이트 | ✅ | 마지막 Step에서 |\n| GEMINI.md 상태 업데이트 | ✅ | 시작/종료 시 |\n\n---","keywords":["필수","포함","요소","체크리스트","설명","yaml","프론트매터","description","슬래시","커맨드","목록에","표시됨","실행","조건","언제","워크플로우를","쓰는지","step","담당","에이전트","skill","md","경로","진입"],"rank":1.0},{"id":"2bd028c86a23a0d2","source":".agents/workflows/CUSTOM_GUIDE.md","title":"네이밍 규칙","line":60,"text":"- 파일명: `kebab-case.md` (예: `dep-update.md`, `data-pipeline.md`)\n- 슬래시 커맨드: `/kebab-case` (예: `/dep-update`)\n- Step 번호: 0부터 시작 (사전 판단 필요 시) 또는 1부터 시작\n\n---","keywords":["네이밍","규칙","파일명","kebab","case","md","dep","update","data","pipeline","슬래시","커맨드","step","번호","부터","시작","사전","판단","필요","또는"],"rank":1.0},{"id":"1a2c74eed01ee0ed","source":".agents/workflows/CUSTOM_GUIDE.md","title":"등록 방법","line":68,"text":"1. `.agents/workflows/` 디렉터리에 `.md` 파일 생성\n2. YAML 프론트매터에 `description` 포함\n3. 에이전트 시스템이 자동으로 슬래시 커맨드로 인식\n\n> 별도 설정 파일 수정 없이, 파일 생성만으로 등록됩니다.","keywords":["등록","방법","agents","workflows","디렉터리에","md","파일","생성","yaml","프론트매터에","description","포함","에이전트","시스템이","자동으로","슬래시","커맨드로","인식","별도","설정","수정","없이","생성만으로","등록됩니다"],"rank":1.0},{"id":"46adf4bdaa2a752a","source":".agents/workflows/dep-update.md","title":"/dep-update","line":1,"text":"1. 변경 이유와 호환 범위를 확인합니다.\n2. 사용자 승인 후 잠금 파일과 선언 파일만 갱신합니다.\n3. 단일 Python·브라우저 테스트를 실행합니다.\n4. 라이선스·취약점·배포 포함 여부를 확인합니다.\n5. 필요하면 `scripts/build_release.py`로 새 배포물을 검증합니다.\n\n사용자 프로젝트의 의존성은 해당 `workspace/projects/<name>/` 내부에서 별도로 관리합니다.","keywords":["dep","update","변경","이유와","호환","범위를","확인합니다","사용자","승인","잠금","파일과","선언","파일만","갱신합니다","단일","python","브라우저","테스트를","실행합니다","라이선스","취약점","배포","포함","여부를"],"rank":1.0},{"id":"4ee074a6b4e3da8d","source":".agents/workflows/dev-cycle.md","title":"개발 흐름","line":1,"text":"1. 주 실행자: 실제 원본·규칙·요청을 읽고 적용 위치와 완료 조건을 정한다.\n2. 복잡한 구조 변경만 Architect와 ultra-plan으로 검토한다. UI 변경에는 designer 스킬을 읽는다.\n3. 구현자는 소스와 관련 테스트를 수정하고 화면·동작을 검증한다.\n4. 독립 검토가 필요하고 호출 도구가 있으면 검토자에게 diff·요구사항·디자인·검증 증거를 전달한다.\n5. 실패와 디자인 차이를 수정한 뒤 관련 검사를 다시 실행한다.\n6. 릴리스 전 Python·브라우저·패키지 검증을 수행하고 docs/log.md에 결과를 기록한다.\n\n역할 명칭을 순서대로 말하는 것만으로 별도 에이전트가 실행되지는 않는다. 호출·회수는 호스트의 실제 기능을 사용한다.\nVAS는 다른 사용자 프로젝트를 복사·실행하지 않으며, 생성 대상 작업은 사용자가 연 코딩 도구의 실제 폴더에서 수행한다.","keywords":["개발","흐름","실행자","실제","원본","규칙","요청을","읽고","적용","위치와","완료","조건을","정한다","복잡한","구조","변경만","architect","ultra","plan","검토한다","ui","변경에는","designer","스킬을"],"rank":1.0},{"id":"916d269d90fbdc3f","source":".agents/workflows/hotfix.md","title":"/hotfix","line":1,"text":"1. 재현 조건과 영향 범위를 고정합니다.\n2. 가장 작은 수정과 회귀 테스트를 함께 추가합니다.\n3. 관련 Python·브라우저 테스트를 실행합니다.\n4. 비밀·사용자 데이터·생성물이 Git에 없는지 확인합니다.\n5. 필요할 때만 릴리즈를 다시 생성합니다.\n\n긴급 수정도 기존 프로젝트 원본 보호와 동의 기반 개인화 규칙을 우회하지 않습니다.","keywords":["hotfix","재현","조건과","영향","범위를","고정합니다","가장","작은","수정과","회귀","테스트를","함께","추가합니다","관련","python","브라우저","실행합니다","비밀","사용자","데이터","생성물이","git","없는지","확인합니다"],"rank":1.0},{"id":"c79f3071a9568ae6","source":".agents/workflows/migration-cycle.md","title":"/migration-cycle","line":1,"text":"기존 프로그램을 VAS에 안전하게 연결하는 흐름입니다.\n\n1. 사용자가 VAS에서 원래 프로젝트 폴더를 선택합니다.\n2. VAS가 파일을 실행하거나 변경하지 않고 구조·스택·위험 요소를 분석합니다.\n3. 사용자가 작업 내용과 디자인을 확인합니다.\n4. VAS가 `VAS-AI-HANDOFF.json`과 붙여넣을 프롬프트를 만듭니다.\n5. 사용자가 Codex·Claude·Antigravity에서 원래 폴더와 JSON을 함께 엽니다.\n6. 코딩 도구가 실제 파일을 다시 확인한 뒤 안전한 변경 계획을 세웁니다.\n\n기존 복사·등록·롤백 모듈은 호환용 내부 기능으로만 남깁니다. VAS 기본 화면은 원본을 실행·수정·삭제하지 않습니다.","keywords":["migration","cycle","기존","프로그램을","vas","안전하게","연결하는","흐름입니다","사용자가","원래","프로젝트","폴더를","선택합니다","파일을","실행하거나","변경하지","않고","구조","스택","위험","요소를","분석합니다","작업","내용과"],"rank":1.0},{"id":"d01e9efbec09338a","source":".agents/workflows/setup-from-application.md","title":"/setup-from-application","line":1,"text":"1. `VAS-AI-HANDOFF.json`의 형식과 필수값을 검증합니다.\n2. 사용자가 코딩 도구에서 연 빈 폴더를 작업 대상으로 확인합니다.\n3. JSON의 요구사항·디자인·안전 제외 규칙을 읽습니다.\n4. 이해한 구조와 첫 작업 계획을 사용자에게 짧게 알립니다.\n5. 승인된 범위 안에서 새 프로그램을 구현하고 검증합니다.\n\nVAS는 작업 폴더를 만들거나 등록하지 않습니다. 참고 파일 내용·연락처·개인화 기록은 인계 JSON에 넣지 않습니다.","keywords":["setup","application","vas","ai","handoff","json","형식과","필수값을","검증합니다","사용자가","코딩","도구에서","폴더를","작업","대상으로","확인합니다","요구사항","디자인","안전","제외","규칙을","읽습니다","이해한","구조와"],"rank":1.0},{"id":"41fdb56f29a45900","source":".agents/workflows/ultra-plan.md","title":"복잡한 설계 비교","line":1,"text":"신규 아키텍처, 기술 이전, 다수 접근법의 성능 개선처럼 선택의 영향이 큰 경우에 사용한다.\n1. 원본을 읽고 비교할 관점과 검증 조건을 정한다.\n2. 실제 서브에이전트 도구가 있고 위임이 적절하면 분리된 탐색을 호출한다. 그렇지 않으면 현재 대화에서 대안을 비교하며 독립 탐색이라고 부르지 않는다.\n3. 인터페이스·유지보수·성능·회귀 위험으로 대안을 비교하고 근거가 있는 설계를 선택한다.\n4. 사용자 승인 범위를 벗어나는 변경만 확인한다. 승인된 범위는 `.agents/workflows/dev-cycle.md`의 구현·검증 단계로 이어간다.","keywords":["복잡한","설계","비교","신규","아키텍처","기술","이전","다수","접근법의","성능","개선처럼","선택의","영향이","경우에","사용한다","원본을","읽고","비교할","관점과","검증","조건을","정한다","실제","서브에이전트"],"rank":1.0},{"id":"aa4b6ff7e5923e10","source":"docs/agent-runtime-validation.md","title":"확인한 결과","line":3,"text":"현재 Codex 호스트에서 실제 하위 에이전트 3개를 생성하고, 검토 결과 전달·수정·재검토까지 완료했습니다.\n일반 생성 도구에 VAS 역할 스킬을 명시적으로 읽게 하는 방식입니다. 네이티브 이름 기반 실행으로 기록하지 않습니다.\n\n| 단계 | 실제 실행 결과 |\n|---|---|\n| Designer | 요구사항·화면 파일을 읽고 정확한 토큰, 레이아웃, 키보드 동작을 정의 |\n| Reviewer | 잘못된 primary 색상과 수량 감소 버그를 독립적으로 발견 |\n| Implementer | 검토 결과를 받아 CSS와 JS의 두 부분만 수정 |\n| 브라우저 | 수정 전 5개 실패 → 수정 후 14개 모두 통과 |\n| Reviewer 재검토 | 원본·브라우저 결과·데스크톱/모바일 캡처 확인, 남은 문제 없음 |\n| 변경 범위 | 재검토 전후 요구사항·HTML·CSS·JS의 SHA-256 동일 |\n\n실제 작업 식별자는 `/root/vas_designer_live`, `/root/vas_reviewer_live`, `/root/vas_implementer_live`입니다.\n시험용 로컬 재고 화면에서 수량 10→11→12, 키보드 Space/Enter, primary #123abc, 반경 0, 패딩 24,\n데스크톱 2열·390px 모바일 1열, 넘침과 JavaScript 오류를 확인했습니다.\n수정 전 비교 파일은 에이전트 실행 전 저장한 해시와 바이트 단위로 일치함을 확인했습니다.\n\n브라우저 확인 명령은 `node tests/agent-live-check.cjs <시험 폴더> <증거 폴더>`입니다.\n이 명령만으로 하위 에이전트가 실행되는 것은 아닙니다. 실제 생성·결과 회수 기록과 함께 판정해야 합니다.\n\n재현하려면 `tests/fixtures/agent-live/`의 4개 시험 파일을 새 로컬 임시 폴더에 복사합니다.\n초기 시험 파일은 의도적으로 위 오류 2개를 포함하며 브라우저 검사는 종료 코드 1을 반환해야 합니다.\n실제 Designer·Reviewer에게 요구사항과 시험 파일을 전달하고, 반환 결과를 Implementer에게 넘겨 그 임시 폴더만 수정하게 합니다.\n브라우저 검사가 종료 코드 0을 반환한 뒤 같은 Reviewer에게 결과와 캡처를 전달해 재검토합니다.\n모델 호출은 로그인된 호스트에서 명시적으로 수행하며 일반 CI는 실제 모델을 호출하지 않습니다.","keywords":["확인한","결과","현재","codex","호스트에서","실제","하위","에이전트","개를","생성하고","검토","전달","수정","재검토까지","완료했습니다","일반","생성","도구에","vas","역할","스킬을","명시적으로","읽게","방식입니다"],"rank":1.0},{"id":"0ec2b371c5600ee1","source":"docs/agent-runtime-validation.md","title":"실행 중 발견해 보완한 사항","line":31,"text":"- PATH의 Codex CLI 0.144.1은 현재 계정의 모델을 지원하지 않아 실행에 실패했습니다.\n- 앱 실행기 0.153.4는 현재 모델을 사용하지만, 노출된 생성 도구에 이름 기반 역할 선택 인자가 없었습니다.\n- 따라서 복사 프롬프트에 3개 역할 지침 본문을 포함하고, 실제 지원되는 일반 생성 도구로 전달하도록 변경했습니다.\n- Windows 격리 CLI에서 NAS의 매핑 드라이브를 작업 위치로 사용하면 경로 오류가 발생했습니다. 시험용 작업 파일은 로컬에 두었습니다.\n- VAS 검사 명령은 UNC로 시작해도 이미 연결된 드라이브를 찾아 npm에 전달하며, 새 드라이브 연결이나 전역 설정 변경은 하지 않습니다.","keywords":["실행","발견해","보완한","사항","path","codex","cli","144","현재","계정의","모델을","지원하지","않아","실행에","실패했습니다","실행기","153","사용하지만","노출된","생성","도구에","이름","기반","역할"],"rank":1.0},{"id":"aca4ba41a5af5ebd","source":"docs/agent-runtime-validation.md","title":"검증 범위","line":39,"text":"현재 Codex 호스트의 실제 분업과 결과 회수는 확인했습니다. 독립 실행마다 성공을 보장하는 성능 평가나 전체 제품 검사는 아닙니다.\n일반 하위 에이전트의 권한은 부모에게서 상속될 수 있습니다. 검토자의 파일 미수정은 해시로 확인했으며 별도 샌드박스를 검증했다고 주장하지 않습니다.\n이 PC에서 Claude Code 실행 프로그램을 찾지 못했으므로 Claude 실호출은 미검증입니다.\n네이티브 설정 파일은 유지하되, 호스트의 실제 지원 여부가 우선합니다.","keywords":["검증","범위","현재","codex","호스트의","실제","분업과","결과","회수는","확인했습니다","독립","실행마다","성공을","보장하는","성능","평가나","전체","제품","검사는","아닙니다","일반","하위","에이전트의","권한은"],"rank":1.0},{"id":"f7b8044bac468d8b","source":"docs/clean-copy-package-plan.md","title":"배포 패키지 기준","line":1,"text":"`python scripts/build_release.py`가 `dist/`에 아래 결과를 만듭니다.\n\n- `VAS-2.7.0-windows.zip`: 로컬 서버·프롬프트 생성·선택형 작업 기억 포함 전체 실행본\n- `VAS-Client-Form-2.7.0.zip`: 외부 공유용 독립 설정 폼\n- `pages/`: GitHub Pages용 정적 허브\n- `release-manifest.json`, `SHA256SUMS.txt`: 파일 목록과 검증 해시\n\n`.git`, `workspace`, `dist`, 백업, 캐시, 테스트 결과, 환경 변수, 키 파일은 제외됩니다. 실행 시 필요한 `workspace/`는 로컬 런타임이 새로 만듭니다.","keywords":["배포","패키지","기준","python","scripts","build","release","py","dist","아래","결과를","만듭니다","vas","windows","zip","로컬","서버","프롬프트","생성","선택형","작업","기억","포함","전체"],"rank":1.0},{"id":"1d3d7110ea0d2aac","source":"docs/design-studio-controls.md","title":"디자인 스튜디오 사용 흐름","line":1,"text":"VAS 디자인 스튜디오는 프리셋과 Taste Profile을 조정하고 실제 디자인 토큰과 구현 지침을 코딩 AI에 전달합니다.","keywords":["디자인","스튜디오","사용","흐름","vas","스튜디오는","프리셋과","taste","profile","조정하고","실제","토큰과","구현","지침을","코딩","ai","전달합니다"],"rank":1.0},{"id":"07c735a186ac605a","source":"docs/design-studio-controls.md","title":"사용","line":5,"text":"1. `src/design-controller.html` 또는 허브의 디자인 스튜디오를 엽니다.\n2. 프리셋을 고르고 색상·폰트·간격 등을 조정합니다.\n3. Taste Profile을 자동으로 두거나 원하는 방향을 선택합니다.\n4. 설정을 저장한 뒤 신청서에서 프롬프트를 복사합니다. JSON 저장은 선택입니다.\n5. 코딩 AI에서 실제 작업 폴더를 열고 프롬프트와 참고 파일 원본을 전달합니다.\n\n새 환경은 `awwwards / Editorial Motion`으로 시작합니다. 기존 선택과 사용자 토큰이 우선합니다.","keywords":["사용","src","design","controller","html","또는","허브의","디자인","스튜디오를","엽니다","프리셋을","고르고","색상","폰트","간격","등을","조정합니다","taste","profile","자동으로","두거나","원하는","방향을","선택합니다"],"rank":1.0},{"id":"5d0bcb9ecaf8eda8","source":"docs/design-studio-controls.md","title":"프리셋과 Taste Profile","line":15,"text":"- 프리셋은 색상·폰트·간격·반경·테두리·그림자를 정합니다.\n- 세부 값을 바꾸면 `preset`은 `custom`이 되지만 `basePreset`에 원래 방향을 유지합니다.\n- 자동 Taste Profile은 `basePreset`을 따릅니다. 색상 하나를 바꿔도 디자인 방향이 초기화되지 않습니다.\n- 수동 Taste Profile은 프리셋을 바꿔도 유지되며, 자동 선택으로 되돌릴 수 있습니다.\n- 선택값은 저장·새로고침·되돌리기·화면 이동에서도 유지됩니다.\n- Taste Profile은 프롬프트와 미리보기 배치를 변경합니다. 확정된 색상 등 토큰은 덮어쓰지 않습니다.\n- 미리보기는 방향을 보여주는 샘플입니다. 완성 화면은 실제 프로젝트에서 구현 후 비교해야 합니다.","keywords":["프리셋과","taste","profile","프리셋은","색상","폰트","간격","반경","테두리","그림자를","정합니다","세부","값을","바꾸면","preset","custom","되지만","basepreset","원래","방향을","유지합니다","자동","따릅니다","하나를"],"rank":1.0},{"id":"51a703ef77e02254","source":"docs/design-studio-controls.md","title":"전달 내용","line":25,"text":"프롬프트에는 Designer 스킬 본문, 프로필 규칙, 프리셋 방향, 정확한 디자인 토큰, 사용자 요구사항과 검증 기준이 포함됩니다.\n사용자 요구와 대상 프로젝트 규칙 → 확정된 토큰·참고 자료 → Taste Profile → 프리셋 기본값 순으로 적용합니다.\nVAS 자체의 Vanilla JS·오프라인 제약을 다른 프로젝트의 React 등 기술 스택에 강제하지 않습니다.\n\n참고 URL은 보존합니다. 참고 파일은 이름만 전달하므로 코딩 AI에 원본을 별도로 첨부해야 합니다.\n파일을 받지 못한 AI가 내용을 보았다고 가정하지 않도록 프롬프트에도 안내합니다.","keywords":["전달","내용","프롬프트에는","designer","스킬","본문","프로필","규칙","프리셋","방향","정확한","디자인","토큰","사용자","요구사항과","검증","기준이","포함됩니다","요구와","대상","프로젝트","확정된","참고","자료"],"rank":1.0},{"id":"6a616f524561de9e","source":"docs/design-studio-controls.md","title":"토큰 내보내기","line":34,"text":"- JSON: 현재 토큰 저장·불러오기. 외부 토큰 JSON만 불러오면 출처 프리셋은 `custom`입니다.\n- CSS: CSS 변수로 내보내기.\n- Tailwind: 대상 프로젝트에 맞게 적용할 참고용 설정.","keywords":["토큰","내보내기","json","현재","저장","불러오기","외부","불러오면","출처","프리셋은","custom","입니다","css","변수로","tailwind","대상","프로젝트에","맞게","적용할","참고용","설정"],"rank":1.0},{"id":"e29b57a021161616","source":"docs/design-studio-controls.md","title":"지침 유지보수","line":40,"text":"원본은 `.agents/skills/designer/SKILL.md`, `references/profiles/*.md`, `.agents/HANDOFF-WORKFLOW.md`입니다.\n변경 후 `npm run agents:build`와 `npm run knowledge:index`를 실행합니다.\n생성된 `src/agent-resources.js`는 일반 화면과 독립 신청서에서 같은 지침을 사용하게 합니다.\n\n`npm run test:python`, `npm run test:browser`, `npm run test:package`로 상태 보존·프롬프트·배포 포함 여부를 확인합니다.","keywords":["지침","유지보수","원본은","agents","skills","designer","skill","md","references","profiles","handoff","workflow","입니다","변경","npm","run","build","knowledge","index","실행합니다","생성된","src","agent","resources"],"rank":1.0},{"id":"aeeb3149b70dc6a2","source":"docs/design-system.md","title":"적용 범위","line":3,"text":"VAS 자체 화면은 HTML/CSS/Vanilla JS와 로컬 에셋을 사용하며 외부 CDN·원격 폰트를 추가하지 않습니다.\nVAS가 인계하는 대상 프로젝트는 해당 프로젝트의 기술 스택·브랜드·사용자 요구를 따릅니다.\n기존 React·Vue·디자인 시스템을 임의로 Vanilla JS나 시스템 폰트로 교체하지 않습니다.","keywords":["적용","범위","vas","자체","화면은","html","css","vanilla","js","로컬","에셋을","사용하며","외부","cdn","원격","폰트를","추가하지","않습니다","인계하는","대상","프로젝트는","해당","프로젝트의","기술"],"rank":1.0},{"id":"9cf107d65f103e1e","source":"docs/design-system.md","title":"디자인 기준","line":9,"text":"1. 사용자 요구사항과 대상 프로젝트 규칙을 먼저 확인합니다.\n2. 확정된 토큰·참고 화면·에셋을 시각 명세로 사용합니다.\n3. Taste Profile과 프리셋은 명세에서 결정하지 않은 부분을 보완합니다.\n\n새 설정의 기본값은 `awwwards / Editorial Motion`입니다. 기존 설정은 자동 전환하지 않습니다.\n세부 토큰을 편집해도 `basePreset`으로 원래 디자인 방향을 유지합니다.\n프로젝트 프리셋은 인계·디자인 예시에 적용하며 VAS 허브의 기본 셸 색은 유지합니다.","keywords":["디자인","기준","사용자","요구사항과","대상","프로젝트","규칙을","먼저","확인합니다","확정된","토큰","참고","화면","에셋을","시각","명세로","사용합니다","taste","profile","프리셋은","명세에서","결정하지","않은","부분을"],"rank":1.0},{"id":"a3b3a1c549d85215","source":"docs/design-system.md","title":"구현과 검증","line":19,"text":"- 인계 프롬프트의 정확한 색상·폰트·간격·반경·테두리·그림자를 적용합니다.\n- 정보 우선순위와 작업 흐름에 따라 레이아웃을 선택합니다. 특정 색이나 중앙 정렬을 일괄 금지하지 않습니다.\n- hover·focus·disabled·loading·empty·error 상태와 키보드 동작을 구현합니다.\n- 모션은 선택한 방향과 대상 프로젝트의 도구를 따르며 reduced-motion 설정을 존중합니다.\n- 데스크톱·모바일 화면을 실제 렌더링하고 참고 자료와 비교합니다. 보지 않은 화면의 검증을 주장하지 않습니다.\n\n구체적인 지침은 `.agents/skills/designer/SKILL.md`와 `references/profiles/*.md`에서 관리합니다.\n변경 후 `npm run agents:build`와 `npm run knowledge:index`를 실행합니다.","keywords":["구현과","검증","인계","프롬프트의","정확한","색상","폰트","간격","반경","테두리","그림자를","적용합니다","정보","우선순위와","작업","흐름에","따라","레이아웃을","선택합니다","특정","색이나","중앙","정렬을","일괄"],"rank":1.0},{"id":"4c7b08d63bba2bee","source":"docs/HANDOFF.md","title":"VAS 2.7.0 AI 인계","line":1,"text":"새 프로젝트와 기존 프로그램 모두 같은 간단한 인계 흐름을 사용합니다.\n\n```text\n프롬프트 복사 → 코딩 AI에서 원본 확인 → 실제 작업\n               └ VAS-AI-HANDOFF.json(v3)은 설정 보관이 필요할 때만 선택\n```","keywords":["vas","ai","인계","프로젝트와","기존","프로그램","모두","같은","간단한","흐름을","사용합니다","text","프롬프트","복사","코딩","원본","확인","실제","작업","handoff","json","v3","설정","보관이"],"rank":1.0},{"id":"3ad8f492f37e46f9","source":"docs/HANDOFF.md","title":"사용","line":10,"text":"1. 기존 프로그램은 **폴더 위치**를 골라 복사 프롬프트에 포함합니다.\n2. 새 프로젝트는 빈 폴더, 기존 프로그램은 프롬프트에 적힌 원본 폴더를 코딩 도구에서 엽니다.\n3. VAS에서 복사한 프롬프트를 붙여넣습니다.\n4. 설정 보관이 필요하면 `VAS-AI-HANDOFF.json`도 프로젝트 최상위에 저장합니다.\n5. 참고 파일은 이름만 전달됩니다. 이미지·문서 원본은 코딩 AI에 별도로 첨부합니다.\n\n복사 프롬프트에는 참고 URL, 대상 플랫폼, 기능·데이터 준비 상태, 일정·예산,\n정확한 디자인 토큰과 Designer 스킬·Taste Profile 지침을 함께 넣습니다.\n세부 토큰을 수정해도 원래 프리셋 방향은 유지합니다.\n기본 디자인 예시는 편집·업무·운영·문서·소비자·제작 화면 구성으로 나뉩니다.\n프로필 지침에는 구도, 글자 크기 비율, 간격, 반응형, 상태 확인 기준이 포함됩니다.\n미리보기의 브랜드·문구·숫자·도형은 스타일 비교용이며 실제 프로젝트 데이터로 인계하지 않습니다.\n브랜드 이름의 프리셋은 분위기 참고이며 해당 서비스의 화면을 그대로 복제하는 템플릿이 아닙니다.","keywords":["사용","기존","프로그램은","폴더","위치","골라","복사","프롬프트에","포함합니다","프로젝트는","적힌","원본","폴더를","코딩","도구에서","엽니다","vas","복사한","프롬프트를","붙여넣습니다","설정","보관이","필요하면","ai"],"rank":1.0},{"id":"0637a18fc3a4f6f3","source":"docs/HANDOFF.md","title":"에이전트 실행","line":26,"text":"주 실행자가 원본 확인·구현·검증을 책임집니다. UI 작업은 디자인 계획과 렌더링 비교를 포함합니다.\n실제 하위 에이전트 도구가 있고 역할 분리가 유용할 때만 Designer·Reviewer에 작업을 맡기며 결과를 기다려 반영합니다.\n도구가 없으면 같은 책임을 순서대로 수행하고, 실행하지 않은 에이전트나 검사를 실행했다고 보고하지 않습니다.\n\nVAS 저장소에는 Codex용 `.codex/agents/vas_*.toml`과 Claude Code용 `.claude/agents/vas_*.md`가 있습니다.\n이 설정은 해당 폴더를 연 호스트에서 사용하는 설정입니다. 다른 프로젝트에 프롬프트를 붙였다고 자동 설치되지 않습니다.\n복사 프롬프트에는 도구에 종속되지 않는 작업 절차가 포함되므로 별도 설정 없이도 순차 작업이 가능합니다.\n모델과 실행 권한은 현재 호스트 설정을 따릅니다. 이름으로 역할을 고르는 인자가 없으면 일반 하위 에이전트에 역할 지침 본문과 작업 범위를 직접 전달합니다.\n복사 프롬프트에는 구현자·디자이너·검토자 지침이 포함되어 대상 프로젝트에 VAS 스킬 파일이 없어도 전달할 수 있습니다.\nReviewer의 네이티브 설정은 읽기 전용입니다. 일반 호출은 부모 권한을 상속할 수 있으므로 수정 금지를 명시하고 검토 전후 변경 여부를 확인합니다.\n\n지침 원본은 `.agents/skills/`와 `.agents/HANDOFF-WORKFLOW.md`이며 `npm run agents:build`로 생성본을 갱신합니다.\n개발 저장소에서 `npm run agent:verify`는 실제 Python·브라우저 검사를 실행하고 실패 코드를 반환합니다.\n`npm run test:package` 후 `npm run agent:security`는 배포 경계·파일 목록·원본 해시를 검사합니다.\n이 명령은 테스트 소스와 개발 의존성이 필요하며, 일반 실행 ZIP의 사용자 작업에는 요구하지 않습니다.\n경로 검사 스크립트는 명시적 파일 쓰기의 사전 검사이며 호스트의 샌드박스나 모든 도구 호출을 대신하지 않습니다.\n실제 호출·오류 수정·결과 회수의 확인 범위는 [에이전트 실행 검증](agent-runtime-validation.md)에 기록합니다.","keywords":["에이전트","실행","실행자가","원본","확인","구현","검증을","책임집니다","ui","작업은","디자인","계획과","렌더링","비교를","포함합니다","실제","하위","도구가","있고","역할","분리가","유용할","때만","designer"],"rank":1.0},{"id":"0bb03dbb9ec25fd6","source":"docs/HANDOFF.md","title":"JSON 계약","line":46,"text":"- `workflow`: `handoffId`, 반복 번호, 이전 결과 연결\n- `project`: 이름, 신규·기존 구분, 목표\n- `task`: 요청, 제약, 완료 기준\n- `context.requirements`: 사용자가 확인한 요구사항\n- `context.design`: 프리셋, 토큰, 디자인 지침\n- `context.rag`: 기본값은 비포함\n- `context.continuation`: 기본값은 비포함\n- `qualityGate`: 요구사항·디자인·RAG·개인정보 확인 상태\n- `security`: 원본 불변과 제외 규칙\n- `assistantGuide`: 코딩 도구에 붙여넣을 문장\n- `integrity.payloadSha256`: 인계 내용 연결용 SHA-256\n\n절대 경로, 비밀값, 연락처, 작업 기억 원본은 JSON에 포함하지 않습니다. 사용자가 고른 폴더 위치는 로컬에서 복사하는 프롬프트에만 포함합니다.\n`analysis`와 파일 목록은 포함하지 않으며 실제 구조는 코딩 AI가 원본 폴더에서 확인합니다.","keywords":["json","계약","workflow","handoffid","반복","번호","이전","결과","연결","project","이름","신규","기존","구분","목표","task","요청","제약","완료","기준","context","requirements","사용자가","확인한"],"rank":1.0},{"id":"ceea4ae2f2175561","source":"docs/HANDOFF.md","title":"호환 계약","line":63,"text":"`VAS-AI-RESULT.json` 검증과 RAG 선택 모듈은 이전 데이터 호환을 위해 남아 있지만 일반 화면과 기본 프롬프트에는 표시하지 않습니다. 기본 저장·복사 동작도 반복 작업 영수증을 만들지 않습니다.","keywords":["호환","계약","vas","ai","result","json","검증과","rag","선택","모듈은","이전","데이터","호환을","위해","남아","있지만","일반","화면과","기본","프롬프트에는","표시하지","않습니다","저장","복사"],"rank":1.0},{"id":"455b48faba61a967","source":"docs/HANDOFF.md","title":"RAG와 RBG","line":67,"text":"- RAG: 작업 기억은 사용자가 동의한 디자인 선택 추천에만 쓰며 기본 인계에는 넣지 않습니다.\n- RBG: 코딩 AI가 생성 전에 원본 구조·규칙·진입점·검증 방법을 실제 파일에서 먼저 확인합니다.","keywords":["rag","rbg","작업","기억은","사용자가","동의한","디자인","선택","추천에만","쓰며","기본","인계에는","넣지","않습니다","코딩","ai","생성","전에","원본","구조","규칙","진입점","검증","방법을"],"rank":1.0},{"id":"a79014a67e1e00ea","source":"docs/import-existing-project.md","title":"기존 프로그램 AI로 연결","line":1,"text":"1. **폴더 위치**를 눌러 원본 폴더 위치를 고릅니다.\n2. 프로젝트 이름과 AI에게 맡길 일을 적습니다.\n3. 디자인 방향과 코딩 도구를 선택합니다.\n4. 완성된 프롬프트를 복사해 Codex·Claude·Antigravity에 붙여넣습니다.\n5. 설정 보관이 필요하면 `VAS-AI-HANDOFF.json`도 프로젝트 최상위에 저장합니다.\n\nVAS는 선택한 위치만 프롬프트에 넣고 폴더 내부는 읽지 않습니다. 절대 경로는 JSON·작업 기억에 저장하지 않습니다. 실제 구조 분석과 수정은 코딩 AI가 RBG 규칙으로 담당합니다.\n\n기존 복사·등록·롤백·결과 검토 모듈은 이전 프로젝트 호환을 위해 남겨두지만 일반 화면에서는 사용하지 않습니다.","keywords":["기존","프로그램","ai","연결","폴더","위치","눌러","원본","위치를","고릅니다","프로젝트","이름과","에게","맡길","일을","적습니다","디자인","방향과","코딩","도구를","선택합니다","완성된","프롬프트를","복사해"],"rank":1.0},{"id":"146f030341548672","source":"docs/index.md","title":"사용자 흐름","line":3,"text":"```text\nRun-VAS-System.bat\n  -> 시작 화면\n     -> 새 프로젝트 -> 요구사항 -> 디자인 -> 프롬프트 복사\n     -> 기존 프로그램 -> 폴더 위치 -> 작업 작성 -> 디자인 -> 프롬프트 복사\n  -> 코딩 도구에서 RBG 확인 후 실제 작업\n```\n\nVAS 웹 화면은 프롬프트와 선택 JSON을 만들 때만 사용합니다. 프로젝트 대시보드나 계속 작업 목록은 제공하지 않습니다.","keywords":["사용자","흐름","text","run","vas","system","bat","시작","화면","프로젝트","요구사항","디자인","프롬프트","복사","기존","프로그램","폴더","위치","작업","작성","코딩","도구에서","rbg","확인"],"rank":1.0},{"id":"05c698713848b878","source":"docs/index.md","title":"구성","line":15,"text":"| 영역 | 역할 | 기준 파일 |\n|---|---|---|\n| 시작 | 두 가지 시작 방식 선택 | `src/vas-hub.html` |\n| 새 프로젝트 | 요구사항·디자인·프롬프트와 선택 JSON | `src/client-application.html` |\n| 기존 프로그램 | 폴더 위치·작업·디자인 프롬프트와 선택 JSON | `src/project-import.html` |\n| 공통 도움말·설정 | 작업 순서와 작업 기억 제어 | `src/setup-tools.js` |\n| 디자인 | 프리셋·토큰·에이전트 디자인 지침 | `src/design-controller.html` |\n| 디자인 샘플 | 선택한 토큰으로 실제 샘플 사이트 확인 | `src/design-sample.html` |\n| 검증 앱 | VAS 인계로 만든 별도 Morrow 작업 보드 | `src/proof-app/index.html`, `docs/verification/README.md` |\n| 인계 계약 | 인계 v3 생성과 호환용 결과 v1 검증 | `src/agent-contract.js`, `src/handoff-workflow.js`, `scripts/vas_ai_contract.py` |\n| 호환 모듈 | 결과 JSON 검증·RAG 검토(기본 UI 미노출) | `src/ai-result-import.js`, `src/handoff-context-review.js` |\n| 런타임 | 로컬 웹 실행과 호환 API | `scripts/Start-VAS.ps1` |\n| 배포 | Windows·독립 폼·Pages 생성 | `scripts/build_release.py` |","keywords":["구성","영역","역할","기준","파일","시작","가지","방식","선택","src","vas","hub","html","프로젝트","요구사항","디자인","프롬프트와","json","client","application","기존","프로그램","폴더","위치"],"rank":1.0},{"id":"085d1a714a10b639","source":"docs/index.md","title":"저장·호환","line":31,"text":"- 작업 기억: Windows 사용자 로컬 또는 브라우저 IndexedDB\n- 디자인 설정: 브라우저 저장소와 URL 상태\n- 체크포인트: `.vas_backups/` 최신 10개\n- 배포물: `dist/`\n- 기존 `workspace/` 프로젝트와 복사·등록 모듈은 삭제하지 않지만 기본 UI에는 노출하지 않습니다.","keywords":["저장","호환","작업","기억","windows","사용자","로컬","또는","브라우저","indexeddb","디자인","설정","저장소와","url","상태","체크포인트","vas","backups","최신","10","배포물","dist","기존","workspace"],"rank":1.0},{"id":"81402ef707a878de","source":"docs/index.md","title":"운영 원칙","line":39,"text":"- 모든 기능은 외부 CDN 없이 동작합니다.\n- 저장소가 차단되거나 손상돼도 기본값으로 실행합니다.\n- 작업 기억은 동의 없이 자동 활성화하지 않습니다.\n- 최종 JSON에는 요구사항·디자인·안전 규칙·AI 안내만 포함하며 구조·기술 스택은 추정하지 않습니다.\n- 기존 프로그램의 절대 경로는 복사 프롬프트에만 넣고 JSON·작업 기억에는 저장하지 않습니다.\n- 기본 저장·복사는 인계 영수증을 만들지 않습니다.\n- 호환용 반복 계약을 직접 사용할 때만 ID·해시·sourceType 일치를 필수로 검사합니다.\n- 파일은 500줄 이하로 유지합니다.","keywords":["운영","원칙","모든","기능은","외부","cdn","없이","동작합니다","저장소가","차단되거나","손상돼도","기본값으로","실행합니다","작업","기억은","동의","자동","활성화하지","않습니다","최종","json","에는","요구사항","디자인"],"rank":1.0},{"id":"35d2f0952aa85161","source":"docs/INSTRUCTIONS.md","title":"VAS 2.7.0 개발 규칙","line":1,"text":"- VAS 자체에는 HTML/CSS/Vanilla JS, Python, PowerShell만 사용합니다. 인계 대상 프로젝트는 해당 기술 스택을 유지합니다.\n- 파일당 500줄 이하, 외부 CDN·원격 폰트 금지입니다.\n- 코어 원본은 `src/`, `docs/`, `scripts/`, `tests/`입니다.\n- 신규·기존 기본 흐름은 프롬프트를 복사해 작업을 보내며 `VAS-AI-HANDOFF.json` v3 저장은 선택입니다.\n- 결과 v1과 RAG 검토는 호환 모듈로 보존하되 기본 UI에는 노출하지 않습니다.\n- 기본 인계는 RAG를 포함하지 않으며, 코딩 AI는 RBG로 실제 파일을 먼저 읽습니다.\n- 기존 프로그램의 구조·기술 스택은 VAS에서 추정하지 않고 코딩 AI가 원본 폴더에서 확인합니다.\n- 기존 프로그램의 폴더 위치는 복사 프롬프트에만 포함하고 JSON·작업 기억에는 저장하지 않습니다.\n- 개인화는 명시적 동의가 있어야 하며 최종 JSON에 원본 기록을 넣지 않습니다.\n- 기존 복사·등록 모듈은 호환용으로 보존하되 기본 UI에 노출하지 않습니다.\n- 평소에는 Python·브라우저·패키지 테스트를 실행합니다.\n- 10회 스트레스 검사는 명시적 요청 때만 실행합니다.\n- 에이전트·디자인 지침 변경 후 `npm run agents:build`, `npm run knowledge:index`를 실행합니다.\n- `npm run agent:verify`는 실제 Python·브라우저 검사를 실행합니다. 패키지 생성 후 `npm run agent:security`로 배포 경계와 원본 해시를 확인합니다.\n- 하위 에이전트는 현재 호스트에서 실제 도구를 제공할 때만 호출하며, 지원하지 않으면 동일한 역할을 순차 수행합니다.","keywords":["vas","개발","규칙","자체에는","html","css","vanilla","js","python","powershell","사용합니다","인계","대상","프로젝트는","해당","기술","스택을","유지합니다","파일당","500","이하","외부","cdn","원격"],"rank":1.0},{"id":"b1811a6b3be5928b","source":"docs/log-archive-2026-05-19-to-2026-05-20.md","title":"2026-05-20 Stark 2.4.1 패치: 네오브루탈리즘 테두리 두께 및 버전 최적화 (Stark 2.4.1 패치)","line":3,"text":"- **분류:** `[디자인 QA 및 스타일 튜닝]`\n- **수행 내용:**\n  1. **네오브루탈리즘 디폴트 테두리 두께 슬림화:** 카드의 4px 보더가 다소 둔탁하고 과하게 굵다는 사용자 피드백을 반영하여, 세련되면서도 강렬한 느낌을 동시에 주는 `2px`로 전격 슬림화(Manual Override 프리셋 `neobrutal` 내 `bw`를 `4`에서 `2`로 조정).\n  2. **디폴트 로더 버전 패치(v2.4.1):** 사용자가 F5 새로고침 시 이 2px 슬림 보더 네오브루탈리즘 테마가 즉각적이고 완벽하게 자동 주입/복원되도록 `CURRENT_VERSION` 플래그를 `'2.4.1'`로 전격 격상.\n  3. **디자인 스튜디오 버전 및 프롬프트 개선:** 디자인 스튜디오(`src/design-controller.html`)의 프리셋 저장 버전도 `'2.4.1'`로 통일하고, AI 프롬프트 설명도 슬림화된 2px 보더 사양에 맞게 미세 튜닝 완료.\n  4. **무결성 100% 검증 및 Final-Centric 동기화:** `src/` 내 수정된 핵심 파일들을 `final/` 배포 경로에 완벽 동기화하고, 131개 통합 무결성 테스트를 가동하여 100% 무결점을 보장함.","keywords":["2026","05","20","stark","패치","네오브루탈리즘","테두리","두께","버전","최적화","분류","디자인","qa","스타일","튜닝","수행","내용","디폴트","슬림화","카드의","4px","보더가","다소","둔탁하고"],"rank":1.0},{"id":"35fe6168b54ec236","source":"docs/log-archive-2026-05-19-to-2026-05-20.md","title":"2026-05-20 로컬 브라우저 구버전 테마 덤프 파괴 및 Stark 강제 복원 (Stark 2.4 패치)","line":12,"text":"- **분류:** `[로컬 브라우저 구버전 테마 덤프 파괴 및 Stark 강제 복원]`\n- **수행 내용:**\n  1. **버전 기반 테마 복원 프레임워크(Versioned Theme Safeguard) 구축:** 구버전 Vercel/Apple 등 둥글둥글한 로컬스토리지 찌꺼기가 브라우저에 남아있어 고객 신청서 페이지(`client-application.html`)가 F5 새로고침을 해도 영구적으로 둥근 형태로 깨져 보이던 심각한 캐싱 부조화를 원천 해결.\n  2. **최초 로드 시 Stark 2.4 강제 자동 패치 구현:** `src/client-application-init.js` 내부에서 `vasThemeTokensVersion` 플래그가 `'2.4'`가 아닌 구버전이거나 존재하지 않는다면, 기존의 모든 둥근 테마 캐시를 무조건 즉시 폭파(Purge)하고, 시그니처 기본 테마인 **Stark Neo-Brutalism(각진 0px 모서리, 4px 검정 굵은 보더, 하드 섀도우)** 디폴트 토큰을 localStorage에 강제 강경 주입하도록 설계.\n  3. **디자인 스튜디오 버전 연동:** 디자인 스튜디오(`src/design-controller.html`)에서 사용자가 명시적으로 수동 프리셋을 지정할 때에만 버전 `'2.4'` 토큰과 테마 정보를 동시 저장하게 세팅하여 신청서와의 영구적인 싱크를 보장.\n  4. **배포본 미러링 및 검증:** 수정한 파일들을 `final/` 폴더에 완벽 동기화하고, 131개 무결성 테스트를 가동하여 100% 올패스 검증 확인 완료.","keywords":["2026","05","20","로컬","브라우저","구버전","테마","덤프","파괴","stark","강제","복원","패치","분류","수행","내용","버전","기반","프레임워크","versioned","theme","safeguard","구축","vercel"],"rank":1.0},{"id":"ee274323f19472e3","source":"docs/log-archive-2026-05-19-to-2026-05-20.md","title":"2026-05-20 디자인 스튜디오 기본 테마 및 초기화 오류 개선 (Neo-Brutalism 기본값 설정)","line":21,"text":"- **분류:** `[디자인 스튜디오 기본 테마 및 초기화 오류 개선]`\n- **수행 내용:**\n  1. **디자인 스튜디오 초기 로딩 기본 프리셋 개정:** `src/design-controller.html`에서 브라우저가 최초 실행되거나 아무 버튼도 클릭하지 않은 채 켜졌을 때, `PRESETS.vercel`로 잡혀있어 Vercel 테마(둥근 모서리, 연회색 보더)가 자동으로 `localStorage`에 저장되어 고객 신청서 폼(`client-application.html`)의 각진 검은색 네모 정체성을 깨뜨리던 초기화 로직을 완벽 교정.\n  2. **시그니처 테마 Neo-Brutalism 기본 프리셋화:** 디자인 스튜디오의 최초 활성화 프리셋 및 초기 로드 테마를 **`neobrutal` (Neo-Brutalism)**로 격상. 이로 인해 스튜디오에 처음 접속하거나 초기 구동 시 무조건 이 프로젝트의 원조 비주얼 정체성인 **각진 모서리(0px), 4px의 굵은 검정 테두리, 하드 블랙 섀도우** 테마가 안전하게 자동 설정 및 동적 전파되도록 개선.\n  3. **프로그램 방식 프리셋 적용 예외 처리:** `applyPreset` 함수에서 `event` 객체가 undefined인 상태로 호출되더라도 에러가 발생하지 않도록 예외 처리 코드를 보강하고, target element가 없을 시 HTML attribute 매칭을 통해 올바른 프리셋 버튼에 `active` 클래스가 자동으로 바인딩되도록 유연성 확대.\n  4. **배포본 미러링 완벽 동기화 및 무결성 검증:** 수정된 `src/design-controller.html`과 `docs/log.md`를 `final/` 배포 경로에 완벽히 동기화 복사 완료하고, 131개 시나리오 10-Loop 통합 정합성 검증 테스트를 스모크 1회 구동하여 100% 무결점으로 통과함을 보장.","keywords":["2026","05","20","디자인","스튜디오","기본","테마","초기화","오류","개선","neo","brutalism","기본값","설정","분류","수행","내용","초기","로딩","프리셋","개정","src","design","controller"],"rank":1.0},{"id":"89a29d9ec7354e7c","source":"docs/log-archive-2026-05-19-to-2026-05-20.md","title":"2026-05-20 기본 디자인 정체성 강화 및 배포 동기화 (Stark 테두리 복원)","line":30,"text":"- **분류:** `[기본 디자인 정체성 강화 및 배포 동기화]`\n- **수행 내용:**\n  1. **기본 네모 디자인(네오브루탈리즘 테두리) 복원 및 선명도 강화:** `src/client-style.css`에서 기본 테두리 색상(`--border`)을 흐릿한 연회색(`#e4e4e7`)에서 강력하고 직관적인 Stark 검은색(`#09090b`)으로 전격 개정. 이를 통해 로컬 스토리지에 테마 토큰이 존재하지 않는 기본 초기 구동 상태에서도 고유의 각진 네모 디자인 정체성이 선명하게 드러나도록 보장.\n  2. **배포본 미러링 완벽 동기화:** 수정된 `src/client-style.css` 파일을 안전하게 `final/src/client-style.css`로 동기화(복사) 완료.\n  3. **131개 통합 무결성 테스트 검증:** 10-Loop 통합 검증 테스트(`tests/test_integrity_10loop.py`)를 Fallback 모드로 단 1회 실행하여 131개 시나리오가 100% 정상 통과함을 보장.\n- **교훈/특이사항:**\n  - **동적 테마 전파 메커니즘의 예외 상황:** `design-controller.html`에서 다른 프리셋(예: Vercel, Apple 등 둥글고 희미한 테두리)을 적용할 때 `localStorage`를 통해 고객 신청서 페이지로 스타일 토큰이 동적 전파되며, 이로 인해 원래의 네오브루탈리즘 테두리가 사라진 것처럼 보이는 현상이 발생함. 이러한 동적 연동 구조와 \"네모 디자인\"으로의 즉시 실시간 복구 방법(컨트롤러에서 Neo-Brutalism 버튼 클릭)을 사용자에게 친절하게 가이드하는 것이 유지보수성 측면에서 중요함.","keywords":["2026","05","20","기본","디자인","정체성","강화","배포","동기화","stark","테두리","복원","분류","수행","내용","네모","네오브루탈리즘","선명도","src","client","style","css","색상","border"],"rank":1.0},{"id":"287e6bdad13f7939","source":"docs/log-archive-2026-05-19-to-2026-05-20.md","title":"2026-05-20 컴퓨터 이관 및 오프라인 보장을 위한 시스템 폰트 폴백 스택 고도화","line":40,"text":"- **분류:** `[이식성 및 폰트 세이프가드 보강]`\n- **수행 내용:**\n  1. **시스템 폰트 폴백 스택 주입:** `client-style.css`, `design-controller.css`, `vas-hub.html`에서 오직 웹 CDN 폰트(`Pretendard`, `Geist Mono` 등)에만 기대던 설계를 탈피. 인터넷 연결 유무나 컴퓨터 OS 이관 여부에 영향받지 않도록 `system-ui`, `-apple-system`, `BlinkMacSystemFont`, `Segoe UI`, `ui-monospace`, `SFMono-Regular` 등 OS 안전 시스템 폰트 스택을 대거 보강.\n  2. **동적 테마 패치 복원력 고도화:** `vas-hub.html` 및 `client-application-init.js` 내부의 `localStorage` 기반 테마 복원 스크립트를 정비하여, 프리셋 전환이나 토큰 덮어쓰기 시에도 이중으로 시스템 폴백이 상속되도록 예외 처리.\n  3. **한글 깨짐 주석 정비:** UTF-8 한글 깨짐이 존재하던 `client-application-init.js` 상단의 주석을 바르게 교정.\n  4. **Final-Centric 동기화 및 무결성 검증:** 루트의 변경 사항을 `final/` 내 4개 파일에 완벽 복사 미러링하고, 131개 시나리오 통합 무결성 테스트 100% PASS 확인 완료.\n- **교훈/특이사항:**\n  - **오프라인 퍼스트(Offline-First) 정신:** CDN 웹 폰트는 인터넷 연결 속도 및 신뢰성에 크게 구애받으므로, 컴퓨터가 바뀌는 상황(경로 및 인터넷 환경 단절)을 대비해 CSS 폰트 스택과 JS 문자열 파서의 2중 안전 장치(폴백 스택)를 꼼꼼하게 마련하는 것이 웹앱의 지속가능한 이식성에 절대적으로 유리함.","keywords":["2026","05","20","컴퓨터","이관","오프라인","보장을","위한","시스템","폰트","폴백","스택","고도화","분류","이식성","세이프가드","보강","수행","내용","주입","client","style","css","design"],"rank":1.0},{"id":"cf42f172d8cd9a40","source":"docs/log-archive-2026-05-19-to-2026-05-20.md","title":"2026-05-20 완료 화면 복귀 후 뒤로가기 시 네비게이션 실종 버그 패치","line":51,"text":"- **분류:** `[네비게이션 UX 및 레이아웃 버그 픽스]`\n- **수행 내용:**\n  1. **인라인 디스플레이 스타일 조작 제거:** `showDone()`과 `goBackFromDone()` 함수에서 사용하던 강제 인라인 `style.display = 'none' / 'block'` 조작을 완전히 제거.\n  2. **클래스 기반 가시성 제어 정형화:** CSS `.active` 규칙에 의해 display 속성이 자연스럽게 결정되도록 일관성을 부여하고, opacity 및 transform 트랜지션만 인라인으로 부드럽게 복구되도록 리팩토링.\n  3. **레이아웃 왜곡 원천 차단:** 완료 화면에서 복귀 후 뒤로가기를 할 때 이전 스텝이 투명한 상태로 자리를 차지하여 네비게이션 버튼을 화면 아래로 밀어버리던 기하학적 레이아웃 충돌 문제를 완벽히 해결.\n  4. **무결성 검증 완료:** 131개 검증 시나리오 통합 무결성 테스트 100% PASS 확인 및 `final/` 배포 미러링 완벽 동기화 완료.\n\n---","keywords":["2026","05","20","완료","화면","복귀","뒤로가기","네비게이션","실종","버그","패치","분류","ux","레이아웃","픽스","수행","내용","인라인","디스플레이","스타일","조작","제거","showdone","gobackfromdone"],"rank":1.0},{"id":"f1a4e30a03e12db3","source":"docs/log-archive-2026-05-19-to-2026-05-20.md","title":"2026-05-20 프리뷰 내 전체 텍스트 요소 실시간 자간 동기화","line":62,"text":"- **분류:** `[디자인 QA 및 버그 픽스]`\n- **수행 내용:**\n  1. **실시간 자간 상속 대상 전면 확장:** `src/design-controller.css` 및 `final/src/design-controller.css`에서 특정 선택자(`.adv-preview h2, p, h3` 등)에만 적용되던 `letter-spacing: var(--p-ls, inherit);` 규칙을 `.adv-preview` 하위의 모든 요소(`.adv-preview *`)로 확장.\n  2. **모든 비주얼 컴포넌트 자간 연동 완료:** 스탯 카드(`.p-stat-card`)의 `.label`, `.value`, `.trend` 뿐만 아니라 인풋 필드(`.p-input`), 버튼 등 프리뷰 내 모든 한글/영문 텍스트가 자간 슬라이더 조절 시 100% 동기화되어 실시간 반응하도록 해결.\n  3. **통합 테스트 자가 검증:** `test_integrity_10loop.py` 를 실행하여 131개 무결성 테스트 항목 100% 올패스 통과.\n- **교훈/특이사항:**\n  - **CSS 변수 상속의 활용:** 프리뷰 컴포넌트 내부에서 일부 요소만 자간이 누락되는 파편화를 방지하기 위해서는, 특정 태그를 전수 나열하기보다 와일드카드(`*`) 상속 설계를 적용하여 뷰 컨테이너 전체의 통일성을 확보하는 것이 훨씬 견고함.\n\n---","keywords":["2026","05","20","프리뷰","전체","텍스트","요소","실시간","자간","동기화","분류","디자인","qa","버그","픽스","수행","내용","상속","대상","전면","확장","src","design","controller"],"rank":1.0},{"id":"946141554fb6a7dd","source":"docs/log-archive-2026-05-19-to-2026-05-20.md","title":"2026-05-20 루트 폴더 레이아웃 초간소화 및 디렉토리 대정리","line":74,"text":"- **분류:** `[구조 최적화 + 테스트 아키텍처 고도화]`\n- **수행 내용:**\n  1. **루트 간소화:** 루트 경로를 `README.md`, `Run-VAS-System.bat`, `vas-hub.html` 3대 핵심 파일로 압축 및 격리하여 비기술자의 복잡도 장벽 완화.\n  2. **논리적 서브폴더 구성:** 핵심 코드는 `src/`, 백업 스크립트는 `scripts/`, 가이드는 `docs/` 및 `.agents/`로 이관.\n  3. **자가 검증 테스트 실행기 구축:** `test_html_syntax.py`, `test_client_form.py` 등을 `pytest` 없이 파이썬 기본 인터프리터로 직접 실행하는 Direct Python Runner 탑재.\n  4. **한글 자간 동기화 패치:** 자간 슬라이더 조절 시 프리뷰 한글이 반응하지 않는 현상 수정을 위해 `--p-ls` 변수 바인딩 적용.\n  5. **Final-Centric 동기화:** `final/` 폴더 내 구조와 바이트 크기를 루트의 최신 상태와 100% 미러링 완료.\n- **교훈/특이사항:**\n  - **구조적 직관성과 이식성:** 비기술적 사용자들의 경험(UX)은 직관적인 루트 폴더 구조에서 출발하며, 서드파티 의존성(`pytest` 등)이 없어도 단위 테스트가 가능하게 설계하는 것이 장기적 이식성에 유리함.\n\n---","keywords":["2026","05","20","루트","폴더","레이아웃","초간소화","디렉토리","대정리","분류","구조","최적화","테스트","아키텍처","고도화","수행","내용","간소화","경로를","readme","md","run","vas","system"],"rank":1.0},{"id":"f6cd99ffa1c006c0","source":"docs/log-archive-2026-05-19-to-2026-05-20.md","title":"2026-05-19 마이그레이션 아카이빙 자동화","line":88,"text":"- **분류:** `[인프라 강화]`\n- **수행 내용:**\n  1. `vas-migration-archive.py` 신규 구축: 원본 프로젝트 스캔 및 백업 압축 배치. ZIP 검증 및 중복 격리 등 5중 안전장치 탑재.\n  2. `migration-cycle.md` Step -1 추가하여 자동 아카이빙 연동.\n- **교훈/특이사항:**\n  - **보관 정책 이원화:** `.vas_backups/`(체크포인트 10개)와 `.temp data/`(백업 1개)의 주기를 달리 관리하여 디스크 효율성 극대화.\n\n---","keywords":["2026","05","19","마이그레이션","아카이빙","자동화","분류","인프라","강화","수행","내용","vas","migration","archive","py","신규","구축","원본","프로젝트","스캔","백업","압축","배치","zip"],"rank":1.0},{"id":"7d5f71ce186cad82","source":"docs/log-archive-2026-05-19-to-2026-05-20.md","title":"2026-05-19 프로젝트 무결성 감사 + 마이그레이션 보강","line":99,"text":"- **분류:** `[유지보수 + 인프라 강화]`\n- **수행 내용:**\n  1. 백업 오타 교정, `final/` 15개 파일 크기 동기화 및 `test_integrity_10loop.py` 검증 항목 대폭 강화 (98건).\n  2. `test_dryrun_10scenarios.py`를 통한 10종 프로젝트 시뮬레이션 및 정규식 단어 경계(`\\b`) 버그 해결.\n- **교훈/특이사항:**\n  - **서브스트링 매칭 함정:** `\"invoice\"` 안에 `\"voice\"`가 잘못 매칭되는 true-positive 예방을 위해 regex 단어 경계(`\\b`) 필수 적용.\n\n---\n\n2026-05-19 이전 레거시 요약은 [`log-archive-pre-2026-05-19.md`](log-archive-pre-2026-05-19.md)에 보관합니다.","keywords":["2026","05","19","프로젝트","무결성","감사","마이그레이션","보강","분류","유지보수","인프라","강화","수행","내용","백업","오타","교정","final","15","파일","크기","동기화","test","integrity"],"rank":1.0},{"id":"4db836a3e9345f6e","source":"docs/log-archive-pre-2026-05-19.md","title":"2026-05-19 이전 작업 이력 보관","line":1,"text":"> 아래 시기의 색상 고정, 허브 격리, `final/` 미러 중심 규칙은 현재 지침이 아닙니다. 현행 기준은 `INSTRUCTIONS.md`, `design-system.md`, `HANDOFF.md`입니다.","keywords":["2026","05","19","이전","작업","이력","보관","아래","시기의","색상","고정","허브","격리","final","미러","중심","규칙은","현재","지침이","아닙니다","현행","기준은","instructions","md"],"rank":1.0},{"id":"4473a3dd332fd487","source":"docs/log-archive-pre-2026-05-19.md","title":"레거시 행동 규칙","line":5,"text":"- 작업 원본은 `src/`, `docs/`, `scripts/`, `tests/`이며 배포물은 스크립트로 생성합니다.\n- 화면은 디자인 스튜디오 토큰과 상태 브리지를 사용하고 임의의 고정 색상으로 분리하지 않습니다.\n- 단일 검증은 평소 실행하며 10회 스트레스 검사는 사용자가 명시한 경우에만 실행합니다.","keywords":["레거시","행동","규칙","작업","원본은","src","docs","scripts","tests","이며","배포물은","스크립트로","생성합니다","화면은","디자인","스튜디오","토큰과","상태","브리지를","사용하고","임의의","고정","색상으로","분리하지"],"rank":1.0},{"id":"ef26f2529073ef0d","source":"docs/log-archive-pre-2026-05-19.md","title":"2026-05-19 ~ 2026-05-17 요약","line":11,"text":"- **2026-05-19 [코드 품질 감사 및 분리]:** `client-application.html` 인라인 스크립트를 `client-application-init.js`로 분리하고 CSS를 모듈화했습니다.\n- **2026-05-19 [Auto-Orchestrator 도입]:** 에이전트 간 연속 실행 프로토콜과 프론트엔드 경량 검증 규칙을 추가했습니다.\n- **2026-05-19 [디자인 정합성 복구]:** 당시 원격 폰트 문제를 수정했습니다. 현재는 오프라인 시스템 폰트만 사용합니다.\n- **2026-05-19 [client-application UX 수술]:** 완료 화면 이동과 선택 상태, 초기화, 오프라인 감지를 보강했습니다.\n- **2026-05-18 [LLM Wiki 아키텍처 통합]:** 파편화된 기록을 `docs/log.md`에 통합했습니다.\n- **2026-05-18 [전체 에이전트 품질 점검]:** 세션 건강도 로직과 HTML 문법 검사를 분리했습니다.\n- **2026-05-17 [Phase 1 완료]:** 독립형 로컬 HTTP 서버와 초기 디자인 화면을 구축했습니다.","keywords":["2026","05","19","17","요약","코드","품질","감사","분리","client","application","html","인라인","스크립트를","init","js","분리하고","css","모듈화했습니다","auto","orchestrator","도입","에이전트","연속"],"rank":1.0},{"id":"3b9b2bd7fdd645c6","source":"docs/MIGRATION.md","title":"마이그레이션 호환 정책","line":1,"text":"VAS 2.7.0의 기본 마이그레이션은 원본 폴더를 코딩 도구에서 열고 `VAS-AI-HANDOFF.json`을 전달하는 방식입니다. VAS가 원본을 복사하거나 등록하지 않습니다.\n\n이전 버전에서 만든 `workspace/projects/`와 백업·복제·검증·롤백 모듈은 데이터 호환을 위해 삭제하지 않습니다. 기본 UI에서는 노출하지 않으며 유지보수용 CLI에서만 사용할 수 있습니다.\n\n```powershell\npython scripts/vas-project-import.py --help\n```\n\nCLI 사용 시에도 원본 실행 금지, 링크 차단, 비밀값 제외, 백업 후 해시 검증 규칙을 유지합니다.","keywords":["마이그레이션","호환","정책","vas","기본","마이그레이션은","원본","폴더를","코딩","도구에서","열고","ai","handoff","json","전달하는","방식입니다","원본을","복사하거나","등록하지","않습니다","이전","버전에서","만든","workspace"],"rank":1.0},{"id":"3a8a38b62b273f25","source":"docs/OPERATIONS.md","title":"실행","line":3,"text":"- 일반 사용자: `Run-VAS-System.bat` 더블클릭\n- 수동 실행: `powershell -ExecutionPolicy Bypass -File scripts/Start-VAS.ps1`\n- 사용하지 않으면 로컬 서버는 기본 30분 뒤 종료됩니다.\n\nVAS는 기존 프로그램의 폴더 위치만 프롬프트에 넣고 내부는 분석하지 않습니다. 실제 구조·기술 스택·실행 방법은 Codex·Claude·Antigravity가 원본 폴더에서 확인합니다.\n\n기본 화면은 새 작업 지시를 만드는 데만 사용합니다. 결과 불러오기와 RAG 검토 모듈은 호환용으로만 보존합니다.","keywords":["실행","일반","사용자","run","vas","system","bat","더블클릭","수동","powershell","executionpolicy","bypass","file","scripts","start","ps1","사용하지","않으면","로컬","서버는","기본","30","종료됩니다","기존"],"rank":1.0},{"id":"43e81956fed636ae","source":"docs/OPERATIONS.md","title":"저장과 복구","line":13,"text":"- 코어 체크포인트: `.vas_backups/checkpoint_*.zip` 최신 10개\n- Windows 작업 기억: `%LOCALAPPDATA%\\QUINTPACT\\VAS\\`\n- 브라우저 작업 기억: IndexedDB\n- 기존 프로젝트·가져오기 자료: `workspace/`에 그대로 보존","keywords":["저장과","복구","코어","체크포인트","vas","backups","checkpoint","zip","최신","10","windows","작업","기억","localappdata","quintpact","브라우저","indexeddb","기존","프로젝트","가져오기","자료","workspace","그대로","보존"],"rank":1.0},{"id":"38d5cbc07869688d","source":"docs/OPERATIONS.md","title":"개인정보","line":20,"text":"- 기본값은 작업 기억 사용 안 함입니다.\n- 동의 전 이벤트를 기록하지 않습니다.\n- 설정에서 사용·중지·삭제·전체 초기화를 언제든 실행할 수 있습니다.\n- 비밀값, 파일 내용, 절대 경로, 파일명은 작업 기억에 저장하지 않습니다.\n- 최종 JSON에는 연락처와 작업 기억 원본을 넣지 않습니다.\n- 사용자가 고른 폴더 위치는 복사 프롬프트에만 사용하고 JSON·작업 기억·선택 기록 파일에는 저장하지 않습니다.\n- 신청서 초안은 복구용으로만 브라우저에 저장하며 JSON 저장 뒤 삭제합니다.","keywords":["개인정보","기본값은","작업","기억","사용","함입니다","동의","이벤트를","기록하지","않습니다","설정에서","중지","삭제","전체","초기화를","언제든","실행할","있습니다","비밀값","파일","내용","절대","경로","파일명은"],"rank":1.0},{"id":"3475b3f9498e48c3","source":"docs/OPERATIONS.md","title":"검증","line":30,"text":"```powershell\nnpm.cmd run knowledge:check\nnpm.cmd run test:python\nnpm.cmd run test:browser\nnpm.cmd run test:package\n```\n\n`npm.cmd run test:release`의 10회 반복은 명시적 요청 때만 실행합니다.","keywords":["검증","powershell","npm","cmd","run","knowledge","check","test","python","browser","package","release","10","반복은","명시적","요청","때만","실행합니다"],"rank":1.0},{"id":"0557cb6539b33ce7","source":"docs/OPERATIONS.md","title":"배포","line":41,"text":"`npm.cmd run release:build` 후 `dist/SHA256SUMS.txt`와 ZIP의 `manifest.json`을 확인합니다. `.git`, `workspace`, 백업, 캐시, 환경 변수, 작업 기억은 배포에서 제외합니다.","keywords":["배포","npm","cmd","run","release","build","dist","sha256sums","txt","zip","manifest","json","확인합니다","git","workspace","백업","캐시","환경","변수","작업","기억은","배포에서","제외합니다"],"rank":1.0},{"id":"149bb39e81be5b6e","source":"docs/releases/2.6.1.md","title":"VAS 2.6.1","line":1,"text":"프로젝트가 화면마다 끊기지 않도록 새 프로젝트·기존 프로그램·디자인·RAG·안전 인계를 하나의 흐름으로 연결했습니다.","keywords":["vas","프로젝트가","화면마다","끊기지","않도록","프로젝트","기존","프로그램","디자인","rag","안전","인계를","하나의","흐름으로","연결했습니다"],"rank":1.0},{"id":"413defce69bd2146","source":"docs/releases/2.6.1.md","title":"주요 변경","line":5,"text":"- Awwwards Editorial 기준의 공통 데스크톱·모바일 레이아웃\n- 프로젝트 컨텍스트와 레지스트리 v2 단계 복원\n- 현재 프로젝트에만 한정된 동의 기반 자동 RAG\n- 기존 프로그램 분석·복제·색인 선택 흐름 개선\n- 원본 소스와 비밀값을 제외한 안전 인계 ZIP\n- 320px부터 데스크톱까지 반응형·키보드·저장소 실패 검증","keywords":["주요","변경","awwwards","editorial","기준의","공통","데스크톱","모바일","레이아웃","프로젝트","컨텍스트와","레지스트리","v2","단계","복원","현재","프로젝트에만","한정된","동의","기반","자동","rag","기존","프로그램"],"rank":1.0},{"id":"d6598ab0d7aff6fe","source":"docs/releases/2.6.1.md","title":"호환성","line":14,"text":"기존 테마 키와 색상·간격 값은 유지합니다. 레거시 폰트 값만 오프라인 시스템 글꼴로 정규화합니다. `v2.6.0` 태그와 외부 백업은 그대로 보존합니다.","keywords":["호환성","기존","테마","키와","색상","간격","값은","유지합니다","레거시","폰트","값만","오프라인","시스템","글꼴로","정규화합니다","v2","태그와","외부","백업은","그대로","보존합니다"],"rank":1.0},{"id":"21ca37982db3c8f6","source":"docs/releases/2.6.2.md","title":"VAS 2.6.2","line":1,"text":"기존 프로그램을 복사하지 않고도 코딩 AI에 안전하게 연결하는 AI 전달팩 흐름을 추가했습니다.","keywords":["vas","기존","프로그램을","복사하지","않고도","코딩","ai","안전하게","연결하는","전달팩","흐름을","추가했습니다"],"rank":1.0},{"id":"ab3eae65e48bcdc6","source":"docs/releases/2.6.2.md","title":"주요 변경","line":5,"text":"- 폴더 선택 → 읽기 전용 분석 → 전달 범위 확인 → JSON/ZIP 저장과 프롬프트 복사\n- Codex·Claude·Antigravity에 공통으로 쓰는 `VAS-AI-HANDOFF.json`\n- 사용자가 직접 고른 텍스트 발췌만 담는 검토 소스 ZIP\n- 등록 프로젝트의 요구사항·디자인·활성 RAG 연결, 개인화 메모리 기본 제외\n- 기존 복사 마이그레이션을 고급 기능으로 유지\n- Awwwards Editorial 기준의 비대칭 3영역 데스크톱·모바일 레이아웃\n- 절대 경로·Git 내부·캐시·비밀값·링크·바이너리 차단과 원본 변경 재검증\n\n기존 진입점, 테마 저장 키, 프로젝트 레지스트리와 2.6.1 백업은 그대로 호환됩니다.","keywords":["주요","변경","폴더","선택","읽기","전용","분석","전달","범위","확인","json","zip","저장과","프롬프트","복사","codex","claude","antigravity","공통으로","쓰는","vas","ai","handoff","사용자가"],"rank":1.0},{"id":"16af0b11edcd352e","source":"docs/releases/2.6.3.md","title":"VAS 2.6.3","line":1,"text":"VAS를 상시 프로젝트 대시보드에서 단계형 초기 설정·AI 인계 도구로 단순화했습니다.\n\n- 첫 화면에는 두 가지 시작 선택만 표시\n- 사용 방법과 작업 기억 설정을 모든 단계에서 다시 열 수 있음\n- 새 프로젝트와 기존 프로그램 모두 `VAS-AI-HANDOFF.json` 생성\n- 기존 프로그램의 구조 추정을 제거하고 실제 소스 분석을 코딩 AI에 위임\n- 기존 프로그램의 폴더 위치를 프롬프트에만 포함하고 중복 PROMPT·JSON 탭 제거\n- JSON보다 자체 완결형 PROMPT를 우선하는 전달 흐름\n- 연락처·절대 경로·비밀값·작업 기억 원본 제외\n- 기존 복사·등록 모듈과 사용자 데이터는 호환용으로 보존","keywords":["vas","상시","프로젝트","대시보드에서","단계형","초기","설정","ai","인계","도구로","단순화했습니다","화면에는","가지","시작","선택만","표시","사용","방법과","작업","기억","설정을","모든","단계에서","다시"],"rank":1.0},{"id":"38096f47a42dc4aa","source":"docs/releases/2.6.4.md","title":"VAS 2.6.4","line":1,"text":"VAS를 `설정 → 프롬프트 복사 → 코딩 AI 작업`에 집중한 초기 설정 도구로 정리했습니다.\n\n- 새 프로젝트·기존 프로그램 모두 프롬프트 복사를 기본 동작으로 통일하고 JSON 저장은 선택 기능으로 유지\n- 기본 프롬프트에서 결과 회수·반복 지시·RAG 원문·내부 인계 ID를 제거\n- 코딩 AI가 원본 파일을 먼저 확인하는 RBG 지침 명시\n- 결과 불러오기·RAG 검토·반복 지시는 기본 UI와 프롬프트에서 제거하고 호환 모듈로만 유지\n- 호환 결과를 직접 불러올 때는 ID·SHA-256·sourceType·안전 플래그를 엄격히 검사\n- 디자인 새 창 설정 동기화, 비저장 폴더 위치 선택, 모바일 도움말과 키보드 포커스 보강\n- 프리셋과 무관하게 VAS 설정 화면의 Awwwards Editorial 대비 유지\n- 외부 요청 없이 오프라인·저장소 차단·모바일 흐름 검증","keywords":["vas","설정","프롬프트","복사","코딩","ai","작업","집중한","초기","도구로","정리했습니다","프로젝트","기존","프로그램","모두","복사를","기본","동작으로","통일하고","json","저장은","선택","기능으로","유지"],"rank":1.0},{"id":"f96ee5e3d6fbf346","source":"docs/releases/2.7.0.md","title":"VAS 2.7.0","line":1,"text":"**Released September 7, 2026**\n\nVAS 2.7.0 expands the design studio with distinct visual collections, interactive sample websites, and a complete application built through the VAS handoff process. It also improves how design choices and role instructions reach the coding agent, with recorded implementation, review, and browser verification.\n\nVAS helps you turn a project request and a chosen design direction into a prompt for your coding tool. The workflow is: describe the work, choose and refine a style, copy the generated prompt, and let the coding agent inspect the actual project before making changes.","keywords":["vas","released","september","2026","expands","design","studio","distinct","visual","collections","interactive","sample","websites","complete","application","built","through","handoff","process","it","also","improves","choices","role"],"rank":1.0},{"id":"488f674b6f88cb0e","source":"docs/releases/2.7.0.md","title":"1. Ten new design collections","line":9,"text":"Each collection has its own composition, typography, visual treatment, and implementation guidance. The previews include real layouts and local assets so you can compare the resulting screens before choosing a direction.","keywords":["ten","new","design","collections","each","collection","has","its","own","composition","typography","visual","treatment","implementation","guidance","previews","include","real","layouts","local","assets","so","you","can"],"rank":1.0},{"id":"53265fa9e37744cf","source":"docs/releases/2.7.0.md","title":"1. Ten new design collections","line":9,"text":"| Collection | Visual direction | Example fit |\n| --- | --- | --- |\n| Bento Studio | Irregular modular layouts, lavender and lime, expressive graphics | Creative studios and personal workspaces |\n| Aurora Glass | Dark atmospheric backgrounds and translucent panels | Immersive product interfaces |\n| Clay Pop | Soft peach colors and rounded 3D objects | Learning experiences and friendly consumer products |\n| Noir Luxe | Dark surfaces, champagne accents, and editorial serif typography | Premium brands and product showcases |\n| Botanical Atelier | Botanical photography, olive tones, and warm ivory | Lifestyle, wellness, and nature-inspired brands |\n| Retro Sunset | Warm retro colors and record-inspired compositions | Music, culture, and independent brands |\n| Swiss Poster | Strong type, disciplined grids, and exhibition-style hierarchy | Events, portfolios, and editorial pages |\n| Cyber Deck | Technical console layouts and high-contrast information | Developer tools and operational interfaces |\n| Kinetic Type | Oversized typography with controllable motion | Creative campaigns and studio presentations |\n| Paper Collage | Layered photographs and tactile editorial compositions | Visual storytelling and independent publications |","keywords":["ten","new","design","collections","collection","visual","direction","example","fit","bento","studio","irregular","modular","layouts","lavender","lime","expressive","graphics","creative","studios","personal","workspaces","aurora","glass"],"rank":1.0},{"id":"8600fdebfe2991b5","source":"docs/releases/2.7.0.md","title":"1. Ten new design collections","line":9,"text":"Fonts and media used by the previews are bundled locally. Font license files are included, and runtime pages do not depend on external font services or CDNs.","keywords":["ten","new","design","collections","fonts","media","used","by","previews","bundled","locally","font","license","files","included","runtime","pages","do","not","depend","on","external","services","or"],"rank":1.0},{"id":"fcd34894d90e6280","source":"docs/releases/2.7.0.md","title":"2. Four curated styles with complete sample websites","line":28,"text":"The recommended legacy styles have been narrowed to four distinct examples. Each recommendation includes a screenshot of its rendered sample and a site you can open and explore.\n\n| Style | Sample site | Interactions you can try |\n| --- | --- | --- |\n| Awwwards | FORM / FIELD architecture studio | Project disclosures, section navigation, and inquiry preview |\n| Linear | ORBIT project board | Task search, task creation, and status changes |\n| Stripe | RELAY subscription service | Monthly/yearly billing comparison and plan selection |\n| Notion | FIELDNOTES team wiki | Document search, document opening, and checklist updates |\n\nThese are demonstration interactions. Inquiry previews do not send messages, and subscription samples do not process payments.\n\nThe main picker now offers **14 curated choices: 10 new collections plus 4 recommended styles**. The complete set of 28 preset definitions remains available for compatibility with previously saved choices.\n\nOpening a sample carries your selected colors, typography, spacing, and profile settings into the preview. Exploring a different sample does not overwrite the design settings you started with.","keywords":["four","curated","styles","complete","sample","websites","recommended","legacy","have","been","narrowed","to","distinct","examples","each","recommendation","includes","screenshot","of","its","rendered","site","you","can"],"rank":1.0},{"id":"c66f13c825cb3fee","source":"docs/releases/2.7.0.md","title":"3. More complete design handoffs","line":45,"text":"VAS now preserves the project requirements, reference URLs, selected preset, confirmed design tokens, and full role instructions more consistently across browser and Python handoff paths.\n\nThis release fixes cases where long instructions were truncated, design token data was incorrectly removed during sanitization, or a small manual edit caused the original preset association to be lost.\n\nThe coding agent receives concrete guidance about layout, typography, spacing, responsive behavior, interaction states, and the chosen visual profile. The sample's fictional content is a visual reference; it is not treated as your project's real business data.\n\nCopying the prompt remains the default handoff action. Saving `VAS-AI-HANDOFF.json` is optional. For an existing project, the coding agent must read the actual source files and preserve that project's technology stack.","keywords":["more","complete","design","handoffs","vas","now","preserves","project","requirements","reference","urls","selected","preset","confirmed","tokens","full","role","instructions","consistently","across","browser","python","handoff","paths"],"rank":1.0},{"id":"7e384904b8a5a46f","source":"docs/releases/2.7.0.md","title":"4. Agent execution backed by actual runs","line":55,"text":"The workflow distinguishes between a host that supports registered VAS roles and a host that can only create general subagents.\n\nWhen general subagents are used, VAS instructions require the complete role text, task scope, assigned files, confirmed design rules, and completion criteria to be passed into the call. The main agent then collects the results, reviews the evidence, routes issues back for correction, and repeats the affected checks.\n\nThe recorded validation includes actual designer, implementer, and reviewer calls. Reviewer instructions prohibit source edits, and file hashes were compared before and after review. Inherited host permissions are not presented as a separate security sandbox.\n\nValidation commands now propagate real failure codes. On Windows, the verification wrapper can reuse an existing mapped drive when npm cannot run directly from a UNC working directory.","keywords":["agent","execution","backed","by","actual","runs","workflow","distinguishes","between","host","that","supports","registered","vas","roles","can","only","create","general","subagents","when","used","instructions","require"],"rank":1.0},{"id":"25045ab26bbe0845","source":"docs/releases/2.7.0.md","title":"5. Morrow: a working application built through VAS","line":65,"text":"The request, original handoff, design specification, and execution results are recorded in `docs/verification/`. The original handoff was generated during development on VAS 2.6.4 and is preserved with its original version and integrity hash.","keywords":["morrow","working","application","built","through","vas","request","original","handoff","design","specification","execution","results","recorded","in","docs","verification","was","generated","during","development","on","is","preserved"],"rank":1.0},{"id":"6d6c4252e8e66864","source":"docs/releases/2.7.0.md","title":"5. Morrow: a working application built through VAS","line":65,"text":"The release includes **Morrow**, a creative task board using the Bento Studio design, at `src/proof-app/index.html`.\n\nMorrow was built from a real five-step VAS project form, an exported handoff, a generated design concept, implementation by a separate agent, and independent review.\n\nIt supports:\n\n- Creating and editing a task title, notes, category, status, and optional due date.\n- Marking tasks complete and combining text search with category and status filters.\n- Archiving and restoring tasks, deleting tasks, and undoing the most recent deletion.\n- Saving data in the browser and exporting the current records as JSON.\n- Clearly labeled example tasks, empty states, input validation, and persistent storage-error guidance.\n- Keyboard operation and responsive layouts at 1440, 768, 390, and 320 pixels.\n\nVerification found and corrected a dialog focus-cycling issue, small mobile completion targets, and a mismatch that allowed more than 5,000 tasks to be saved but rejected them on reload. A browser regression check now creates a 5,001st task and confirms that all 5,001 records remain readable after reloading.\n\nMorrow is a browser-local application. It does not include accounts, a backend, an AI API connection, JSON import, or synchronization between devices.","keywords":["morrow","working","application","built","through","vas","release","includes","creative","task","board","using","bento","studio","design","at","src","proof","app","index","html","was","real","five"],"rank":1.0},{"id":"c9659c78a057519b","source":"docs/releases/2.7.0.md","title":"6. Verification completed before release","line":86,"text":"| Check | Result |\n| --- | --- |\n| Python checks, including Windows runtime coverage | 111 passed; 1 environment-dependent skip |\n| Browser regression scenarios | 75 passed |\n| Release package checks | 7 passed |\n| Extracted Windows package execution in a path containing Korean characters and spaces | 1 passed |\n| Release boundary checks | 4 passed, plus packaged-source hash verification |\n| GitHub CI, Pages deployment, and release publishing workflows | Completed successfully |\n\nBrowser checks cover the VAS setup and handoff flows, design selection and persistence, sample interactions, and Morrow's functional and error states. The public deployment was also checked after publishing.\n\nPublished ZIP digests were checked against both `SHA256SUMS.txt` and `release-manifest.json`. The manifest version and source commit match the release.\n\nThese results describe the tested environments and workflows. They do not establish identical behavior in every coding host or browser. The optional ten-run stress suite was not run for this release.","keywords":["verification","completed","before","release","check","result","python","checks","including","windows","runtime","coverage","111","passed","environment","dependent","skip","browser","regression","scenarios","75","package","extracted","execution"],"rank":1.0},{"id":"32a3ceea9310f2ab","source":"docs/releases/2.7.0.md","title":"7. Downloads and getting started","line":103,"text":"| File | Purpose |\n| --- | --- |\n| `VAS-2.7.0-windows.zip` | Complete Windows distribution with the local launcher, design studio, handoff tools, sample sites, and Morrow |\n| `VAS-Client-Form-2.7.0.zip` | Standalone project request form for sharing |\n| `release-manifest.json` | Release version, source commit, artifact sizes, and hashes |\n| `SHA256SUMS.txt` | SHA-256 checksums for the two ZIP downloads |\n\nFor the complete Windows version:\n\n1. Download `VAS-2.7.0-windows.zip`.\n2. Extract the entire archive into a new folder.\n3. Run `Run-VAS-System.bat` on Windows 10 or 11 with PowerShell 5.1 or later.\n4. Choose a new project or an existing project, describe the work, and select a design.\n5. Open the actual project folder in your coding tool and paste the generated prompt.\n\nKeep the previous installation folder and any user data when upgrading. The application version is now 2.7.0; the handoff v3 and result v1 formats and existing design storage keys remain compatible. Updating the version does not intentionally reset saved settings.\n\nExisting project paths belong only in the copied prompt, not in the exported JSON or work-memory records. Work memory remains opt-in. VAS does not run the existing target project as part of preparing its handoff.","keywords":["downloads","getting","started","file","purpose","vas","windows","zip","complete","distribution","local","launcher","design","studio","handoff","tools","sample","sites","morrow","client","form","standalone","project","request"],"rank":1.0},{"id":"798bd272383ae9c6","source":"docs/verification/creative-board-design.md","title":"확인한 근거","line":3,"text":"- 실제 VAS 인계: `creative-board-handoff.json`, `creative-board-handoff.txt`.\n- 인계 ID: `h_64962914d7d4a1db857cfd995c68da27`.\n- 선택 프로필: `.agents/skills/designer/references/profiles/bentoStudio.md`.\n- 전체 화면 시안: `exec-da81303f-af16-4743-a743-e874d463caef.png`, 1448×1086.\n- 분리한 원본 그림: `exec-5a87dc43-da6c-48eb-8101-780a050a121a.png`, 1122×1402.\n- 두 이미지를 내장 Image Gen으로 생성하고 `view_image`로 확인했다.\n- 이 문서는 디자인 명세다. 구현 후 브라우저 확인 결과는 별도 검증 기록에 남긴다.","keywords":["확인한","근거","실제","vas","인계","creative","board","handoff","json","txt","id","64962914d7d4a1db857cfd995c68da27","선택","프로필","agents","skills","designer","references","profiles","bentostudio","md","전체","화면","시안"],"rank":1.0},{"id":"286b7063d02950ce","source":"docs/verification/creative-board-design.md","title":"화면의 목적과 구성","line":13,"text":"아이디어를 작업으로 추가하고 완료까지 관리하는 개인용 보드다. 모든 작업과 상태는 실제 로컬 데이터에 연결한다. 브랜딩용 소개 페이지나 가짜 통계판을 만들지 않는다.\n\n큰 제목, 서로 다른 비율의 라임 작업 타일·검정 저장 타일·세로 그림 타일, 실제 작업 목록을 조합한다. 상단의 비대칭 타일은 Bento Studio의 정체성을 유지하고 하단은 검색과 편집이 빠른 목록으로 구성한다.","keywords":["화면의","목적과","구성","아이디어를","작업으로","추가하고","완료까지","관리하는","개인용","보드다","모든","작업과","상태는","실제","로컬","데이터에","연결한다","브랜딩용","소개","페이지나","가짜","통계판을","만들지","않는다"],"rank":1.0},{"id":"387d7b5914cacb10","source":"docs/verification/creative-board-design.md","title":"확정 토큰","line":19,"text":"| 항목 | 값 |\n| --- | --- |\n| 배경 | `#e9dff5` |\n| 표면 | `#f8f4fc` |\n| 본문·검정 타일 | `#17121f` |\n| 주요 색상·집중 타일 | `#c8ed47` |\n| 경계 색상 | `#cfc2df` |\n| 성공 색상 | `#10b981` |\n| 타일 모서리·내부 여백 | `24px` / `24px` |\n| 타일 테두리·그림자 | `0` / `0` |\n| 본문·작은 글자 | `16px` / `12.8px` |\n| 제목 단계 | `56px` / `35.2px` / `24px` |\n| 자간·동작 시간 | `-.03em` / `.2s` |\n| 폰트 | 로컬 Bricolage Grotesque + 인계의 시스템 한글 폴백 |\n\n본문 행간은 1.6, 제목 행간은 1.12, 입력·버튼은 16px/1.4로 명시한다. 한글 제목 800, 영문 브랜드 800, 목록 제목 650, 본문 400을 사용한다. 큰 모듈은 확정된 24px 패딩을 적용한다. 입력 경계와 키보드 포커스 표시는 타일 테두리와 별개인 기능 상태다.\n\n라임 배경에는 어두운 글자를, 검정 타일에는 표면색 글자를 사용한다. 성공색만으로 상태를 설명하지 않는다. 원본 그림 안의 산호·분홍·크림은 미디어의 색이며 앱 토큰에 추가하지 않는다. 배경 그라데이션이나 그림의 반투명 색상 덮개를 사용하지 않는다.","keywords":["확정","토큰","항목","배경","e9dff5","표면","f8f4fc","본문","검정","타일","17121f","주요","색상","집중","c8ed47","경계","cfc2df","성공","10b981","모서리","내부","여백","24px","테두리"],"rank":1.0},{"id":"920a0f1a82c75cab","source":"docs/verification/creative-board-design.md","title":"데스크톱 구조","line":40,"text":"- 전체 컨테이너는 최대 1360px, 가운데 정렬. 1440px에서 좌우 40px. 타일 간격 16px.\n- 헤더는 높이 약 72px. 왼쪽 `morrow` 브랜드, 오른쪽 `작업 보드`와 `보관함` 전환. 현재 항목 아래 라임 선. 브랜드는 탐색을 방해하는 별도 장식 없음.\n- 상단 그리드는 약 `1.15fr .9fr 1.15fr`. 제목은 첫 두 열, 그림은 마지막 열 두 행에 걸친다. 제목 최소 높이 330px, 아래 두 타일 약 220px. 고정 높이 대신 내용이 늘면 커지게 한다.\n- 제목 문구는 `좋은 생각을,` / `끝낸 작업으로.` 두 줄. 그 아래 `만들고 싶은 것을 적고, 하나씩 완성하세요.`와 검정 `새 작업` 버튼. 앞의 더하기 아이콘은 실제 SVG.\n- 라임 타일은 `지금 집중할 작업`, 현재 선택 작업의 분류와 예시 여부, 제목, `작업 열기`, 상태를 표시한다. 실제 진행 중 작업 우선, 없으면 미완료 작업을 사용한다. 작업이 없으면 `집중할 작업이 없어요.`와 `새 작업`을 표시한다.\n- 검정 타일은 `이 브라우저에 저장`, 실제 저장 상태 설명, `JSON 내보내기` 버튼. 버튼은 표면색 경계·글자, 검정 배경이다.\n- 오른쪽 그림은 `assets/morrow-print.png`. 타일 영역을 꽉 채우고 `object-fit:cover; object-position:center;`로 표시한다. 텍스트나 버튼을 이미지 위에 겹치지 않는다. 장식용 빈 alt를 사용한다.\n- 하단의 큰 작업 패널은 모든 열을 차지한다. 제목 `모든 작업`, 검색 입력, 상태 필터와 분류 선택, 목록 순서다. 실제 결과가 0이면 빈 상태를 표시한다.\n- 목록은 체크박스, 작업 제목, 분류, 상태, 예시 여부, 기한, 열기 버튼. 작업 제목은 길어도 줄바꿈한다. 메모는 편집 창에서 확인한다. 행 사이 얇은 경계만 사용하고 각 행에 새 카드를 두르지 않는다.\n- 완료 체크박스는 상태를 실제 변경한다. 제목 또는 열기 버튼은 편집 창을 연다. 일반 글자와 필터는 일관된 크기로 유지한다.","keywords":["데스크톱","구조","전체","컨테이너는","최대","1360px","가운데","정렬","1440px","좌우","40px","타일","간격","16px","헤더는","높이","72px","왼쪽","morrow","브랜드","오른쪽","작업","보드","보관함"],"rank":1.0},{"id":"d968d4483d15f101","source":"docs/verification/creative-board-design.md","title":"첫 화면의 문구와 예시","line":53,"text":"허용된 고정 문구: `morrow`, `작업 보드`, `보관함`, `좋은 생각을,`, `끝낸 작업으로.`, `만들고 싶은 것을 적고, 하나씩 완성하세요.`, `새 작업`, `지금 집중할 작업`, `작업 열기`, `이 브라우저에 저장`, `변경 사항은 자동으로 저장돼요.`, `JSON 내보내기`, `모든 작업`, `작업 검색`, `전체`, `할 일`, `진행 중`, `완료`, `모든 카테고리`, `작업`, `카테고리`, `상태`, `예시`, `기한`, `기한 없음`.\n\n첫 실행 예시는 다음 네 개다. 모두 명확하게 `예시`로 표시하며 사용자가 추가한 작업에는 표시하지 않는다.\n\n| 제목 | 분류 | 상태 |\n| --- | --- | --- |\n| Morrow 브랜드 방향 정리 | 브랜딩 | 진행 중 |\n| 스튜디오 웹 첫 화면 만들기 | 웹 | 할 일 |\n| 첫 뉴스레터 원고 다듬기 | 콘텐츠 | 할 일 |\n| 무드보드 모으기 | 브랜딩 | 완료 |\n\n예시가 보일 때만 `예시 작업이 포함되어 있어요. 직접 수정하거나 지워보세요.`를 표시한다. 날짜와 메모는 실제 입력값 또는 `기한 없음`이다. 가짜 시간·완료율·사용자 수를 추가하지 않는다.","keywords":["화면의","문구와","예시","허용된","고정","문구","morrow","작업","보드","보관함","좋은","생각을","끝낸","작업으로","만들고","싶은","것을","적고","하나씩","완성하세요","지금","집중할","열기","브라우저에"],"rank":1.0},{"id":"e9abdb22de73942e","source":"docs/verification/creative-board-design.md","title":"편집과 기능 상태","line":68,"text":"- `새 작업`은 제목·메모·분류·상태·선택 마감일이 있는 네이티브 dialog를 연다. 편집 시 제목은 `작업 수정`. 저장 전의 입력은 취소하면 버린다.\n- 창 너비는 최대 560px, 표면색, 24px 모서리·패딩. 헤더와 닫기, 제목 전체 폭, 메모 전체 폭, 분류·상태 두 열, 마감일, 행동 영역 순서. 화면 높이가 작으면 창 내부가 스크롤된다.\n- 필드 레이블: `제목`, `메모`, `분류`, `상태`, `마감일 (선택)`. 행동: `취소`, `작업 추가` 또는 `변경 저장`. 편집 창에 `보관`, `삭제`를 구분해 배치한다.\n- 제목은 공백만 허용하지 않는다. 오류는 입력 아래 `제목을 입력해 주세요.`와 `aria-invalid`로 연결하고 잘못된 필드에 포커스를 이동한다. 입력 오류 상태에서 창이 닫히거나 내용이 사라지지 않는다.\n- 기본 입력은 표면색과 경계색. 포커스는 어두운 2px 외곽선 + 3px 간격. 검정 타일 안에서는 밝은 외곽선. 비활성은 설명과 disabled 속성, 눈에 보이는 흐린 상태를 함께 사용한다.\n- 저장 성공은 실제 localStorage 쓰기가 끝난 뒤에만 표시한다. 실패하면 검정 저장 타일의 설명을 `브라우저에 저장하지 못했어요. JSON으로 보관해 주세요.`로 교체하고 명확한 상태 안내를 제공한다. 편집된 메모리 데이터는 유지해 내보낼 수 있게 한다.\n- 검색은 제목과 메모를 함께 검색한다. 분류·상태 필터를 동시에 적용한다. 검색 결과가 없으면 `조건에 맞는 작업이 없어요.`와 `필터 초기화`. 완전히 빈 보드는 `첫 작업을 적어보세요.`와 `새 작업`.\n- 보관은 작업 보드에서 숨기고 보관함에서 복원할 수 있게 한다. 삭제는 실행 취소 알림을 제공한다. 알림에는 실제 작업 제목과 `실행 취소`가 있고 키보드로 접근 가능해야 한다.\n- dialog는 제목에 연결하고 포커스를 내부에 유지한다. Esc로 취소하고 닫히면 처음 연 버튼으로 복귀한다. 삭제 후 사라진 행의 포커스는 보드 제목이나 다음 논리적인 제어로 이동한다.\n- 전역 알림은 작업 패널 아래 또는 화면 하단에 16px 여백을 둔다. 모바일에서 입력·저장 버튼을 덮지 않는다. 토스트만으로 저장 실패를 짧게 숨기지 않는다.\n- 예시 데이터도 편집·완료·보관·삭제가 모두 가능하다. 사용자 입력은 textContent/안전한 DOM API로만 표시한다.\n- 저장 키는 `morrow.board.v1` 하나다. 기존 VAS 설정이나 다른 앱의 키를 변경하지 않는다. JSON은 실제 현재 데이터로 내보낸다.","keywords":["편집과","기능","상태","작업","제목","메모","분류","선택","마감일이","네이티브","dialog","연다","편집","제목은","수정","저장","전의","입력은","취소하면","버린다","너비는","최대","560px","표면색"],"rank":1.0},{"id":"9dfd394bc74a4c1d","source":"docs/verification/creative-board-design.md","title":"반응형과 동작","line":83,"text":"| 폭 | 구성 |\n| --- | --- |\n| 1440px | 3열 상단 그리드, 제목 두 열, 오른쪽 그림 두 행, 하단 전체 폭 목록 |\n| 768px | 좌우 24px, 2열. 제목 전체 폭, 그림과 집중 타일을 나란히, 저장 타일 전체 폭. 목록은 제목·메타데이터 중심으로 줄을 재배치 |\n| 390px | 좌우 16px, 한 열. 제목 → 집중 작업 → 짧은 그림 → 저장 → 목록. 제목 36px로 축소. 그림 높이 약 240px. 검색·분류는 전체 폭 |\n| 320px | 좌우 12px, 한 열. 제목 32px. 24px 모듈 패딩 유지. 상태 필터 2×2 배치. 목록의 분류·상태·기한은 제목 아래로 이동 |\n\n좁은 화면의 글자 축소는 확정 데스크톱 토큰을 보존한 반응형 규칙이다. 고정 폭 표를 수평 스크롤시키거나 중요한 작업 정보를 숨기지 않는다. 제목·메모·날짜의 긴 값은 컨테이너 안에서 줄바꿈한다. 버튼·탭·체크박스의 실제 터치 영역은 최소 44px다.\n\n호버는 버튼 밝기 또는 1px 이동 정도, `.2s` 이내. 불필요한 반복 애니메이션은 없다. `prefers-reduced-motion: reduce`에서는 이동과 전환을 제거한다.","keywords":["반응형과","동작","구성","1440px","상단","그리드","제목","오른쪽","그림","하단","전체","목록","768px","좌우","24px","그림과","집중","타일을","나란히","저장","타일","목록은","메타데이터","중심으로"],"rank":1.0},{"id":"fd3119997dc8512f","source":"docs/verification/creative-board-design.md","title":"자산과 구현 인계","line":96,"text":"- 원본 그림의 배포 경로: `src/proof-app/assets/morrow-print.png`.\n- 로컬 폰트: `src/assets/fonts/BricolageGrotesque.ttf`와 저장소의 라이선스 파일.\n- 앱 기본 위치: `src/proof-app/`. HTML/CSS/Vanilla JS, 각 파일 500줄 이하.\n- 이미지 생성 전체 화면은 검증 참고 자료다. 실제 UI 전체를 이미지로 붙이지 않는다. 브랜드·제목·목록·버튼·체크박스는 모두 실제 HTML.\n- 아이콘은 20px, 2px 선, 둥근 끝의 SVG: 더하기, 검색, 열기, 닫기. 체크박스는 접근 가능한 네이티브 입력을 사용한다. 임의의 이모지 장식은 추가하지 않는다.","keywords":["자산과","구현","인계","원본","그림의","배포","경로","src","proof","app","assets","morrow","print","png","로컬","폰트","fonts","bricolagegrotesque","ttf","저장소의","라이선스","파일","기본","위치"],"rank":1.0},{"id":"dd5c6c6afd606411","source":"docs/verification/creative-board-design.md","title":"시안과 토큰의 우선순위 및 검증 계획","line":104,"text":"시안 생성 뒤 실제 인계 JSON을 다시 읽었다. 생성 이미지의 큰 제목이 56px보다 크고 몇몇 안쪽 간격도 24px보다 넓다. 구현은 확정 `fsHero:56px`, `padding:24px`를 우선한다. 화면의 구도·문구·색상 영역·그림은 시안을 따르되 이 두 값의 차이는 의도된 토큰 준수다. 이미지의 미세한 질감이 아닌 실제 CSS 색상은 확정된 단색 값을 사용한다.\n\n생성 이미지에 표현된 전체 선택처럼 보이는 목록 머리 체크박스는 별도 일괄 기능이 요구되지 않았으므로 구현에서 생략한다. 완료 행의 체크 상태는 실제 데이터와 맞춘다. 상태표시와 표 머리 구조를 이 기능적 필요에 맞게 명시적으로 보완한다.\n\n구현 검증자는 시안과 최신 브라우저 캡처를 각각 `view_image`로 열어 다음을 기록한다: 문구와 순서, 비대칭 상단 비율, 확정 글자 크기, 다섯 토큰 색상, 그림 크롭과 무색상 덮개, 24px 모서리·패딩, 모바일 줄바꿈. 이어 추가→수정→완료→검색/필터→보관/복원→삭제/실행 취소→새로고침 유지→JSON 내보내기→저장 오류를 확인한다. 이 문서는 그 검증이 이미 끝났다고 주장하지 않는다.","keywords":["시안과","토큰의","우선순위","검증","계획","시안","생성","실제","인계","json","다시","읽었다","이미지의","제목이","56px","보다","크고","몇몇","안쪽","간격도","24px","넓다","구현은","확정"],"rank":1.0},{"id":"29f8eb5e8498763f","source":"docs/verification/README.md","title":"Morrow 실제 웹앱 검증","line":1,"text":"VAS의 디자인·에이전트 인계가 실제 앱 구현으로 이어지는지 확인하기 위한 개인용 작업 보드다. 실행 화면은 `src/proof-app/index.html`이다.","keywords":["morrow","실제","웹앱","검증","vas","디자인","에이전트","인계가","구현으로","이어지는지","확인하기","위한","개인용","작업","보드다","실행","화면은","src","proof","app","index","html","이다"],"rank":1.0},{"id":"430d1e17380a4589","source":"docs/verification/README.md","title":"요청부터 구현까지","line":5,"text":"1. `creative-board-request.json`의 요구사항으로 VAS 새 프로젝트 신청서 다섯 단계를 실제 입력했다.\n2. Bento Studio를 선택하고 다운로드 버튼으로 `creative-board-handoff.json`을 저장했다.\n3. 완료 화면의 복사 프롬프트를 `creative-board-handoff.txt`와 대조했다. 요청·전체 역할 본문·SHA-256 일치 검사를 통과했다.\n4. 실제 하위 에이전트 `proof_designer`가 전체 인계를 읽고 화면 시안, 분리 그림, `creative-board-design.md`를 만들었다.\n5. 실제 하위 에이전트 `proof_implementer`가 전체 구현자 지침·인계·디자인 명세를 읽고 앱 소스를 작성했다.\n6. `proof_reviewer`에게 전체 검토자 지침과 수정 금지를 전달했다. 주 실행자는 테스트와 캡처를 확인하고 발견된 문제를 구현자에게 돌려보낸다.\n\n호출 도구는 이름으로 등록된 VAS 네이티브 역할을 선택하는 방식이 아니다. 일반 하위 에이전트에 역할 본문·담당 파일·확정 토큰·완료 조건을 전달했다. 검토자는 호스트 권한을 상속하므로 별도 샌드박스라고 주장하지 않는다. 실제 호출 식별자·완료 상태·검토 전후 소스 해시와 최종 검사 결과는 `creative-board-results.json`에 기록한다.","keywords":["요청부터","구현까지","creative","board","request","json","요구사항으로","vas","프로젝트","신청서","다섯","단계를","실제","입력했다","bento","studio","선택하고","다운로드","버튼으로","handoff","저장했다","완료","화면의","복사"],"rank":1.0},{"id":"04a5c850ed1479d5","source":"docs/verification/README.md","title":"앱 범위","line":16,"text":"- 작업 제목·메모·분류·상태·선택 마감일 추가/수정, 완료 전환.\n- 제목과 메모 검색, 분류·상태 필터 조합과 초기화.\n- 보관과 복원, 삭제와 실행 취소, 실제 현재 데이터의 JSON 내보내기.\n- `morrow.board.v1`만 사용하는 브라우저 저장. 초기 네 작업은 예시라고 표시한다.\n- 입력 검증, 빈 목록, 검색 결과 없음, 저장 차단·손상 안내와 원본 보존.\n- 서버·계정·AI API 없는 앱이다. 기기 간 동기화와 JSON 가져오기는 이 검증의 범위에 포함하지 않았다.\n- HTML/CSS/Vanilla JS는 이번 요청의 명시적 선택이다. 다른 VAS 대상 프로젝트의 기술 스택을 제한하지 않는다.","keywords":["범위","작업","제목","메모","분류","상태","선택","마감일","추가","수정","완료","전환","제목과","검색","필터","조합과","초기화","보관과","복원","삭제와","실행","취소","실제","현재"],"rank":1.0},{"id":"12ee29d72eadb206","source":"docs/verification/README.md","title":"시안과 실제 화면 대조","line":26,"text":"| 항목 | 구현 기준과 확인 내용 |\n| --- | --- |\n| 구도 | 제목 두 열, 세로 그림 두 행, 라임 집중·검정 저장 타일, 전체 폭 작업 목록 |\n| 문구 | 시안의 한국어 제목·행동·예시 작업을 실제 HTML로 구현 |\n| 색상 | 인계의 배경·표면·주요 색상·본문·경계 토큰 사용. 그림 위 색상 덮개 없음 |\n| 글자 | 로컬 Bricolage와 시스템 한글 폴백. 생성 시안보다 큰 차이가 나는 제목은 확정된 56px를 우선 |\n| 간격 | 생성 이미지의 넓은 안쪽 여백 대신 확정 패딩·모서리 24px 적용 |\n| 그림 | 시안에서 분리 생성한 그림만 이미지로 사용. UI 전체는 이미지로 붙이지 않음 |\n| 기능 | 가짜 전체 선택 체크박스를 생략하고 완료 예시는 실제 체크 상태로 표시 |\n| 모바일 | 1440/768/390/320px에서 줄바꿈·가로 넘침·입력 창과 버튼 조작 검사 |\n\n첫 집중 검사에서 네이티브 dialog의 Tab 순환 누락을 발견해 명시적 포커스 순환을 추가했다. 저장 읽기 오류 안내에는 저장 실패와 원본 보존 사실을 함께 표시했다. 모바일 완료 체크 영역은 44px로 맞췄다.","keywords":["시안과","실제","화면","대조","항목","구현","기준과","확인","내용","구도","제목","세로","그림","라임","집중","검정","저장","타일","전체","작업","목록","문구","시안의","한국어"],"rank":1.0},{"id":"d4806d9ec353b175","source":"docs/verification/README.md","title":"재현","line":41,"text":"- 인계 다시 생성: `node scripts/build-proof-handoff.cjs` (새 실행의 인계 ID·해시로 검증 자료를 갱신하므로 기존 실행 기록과 구분한다).\n- 앱 검사: `npm run test:browser -- tests/creative-board.spec.js --workers=2 --reporter=line --output <외부 결과 폴더>`.\n- 전체 검사: `npm run test:python`, `npm run test:browser`, `npm run test:package`, `npm run agent:security`.\n- 자동 브라우저 검사는 새 브라우저 컨텍스트를 사용한다. 사용자 브라우저의 기존 저장 공간을 지우지 않는다.\n- 실험 결과는 이번 앱과 실행 호스트의 검증이다. 모든 코딩 도구·프로젝트에서 항상 같은 결과가 나온다는 보장은 아니다.","keywords":["재현","인계","다시","생성","node","scripts","build","proof","handoff","cjs","실행의","id","해시로","검증","자료를","갱신하므로","기존","실행","기록과","구분한다","검사","npm","run","test"],"rank":1.0}]});
})(typeof window!=='undefined'?window:globalThis);
